INSERT INTO `markets` (`id`, `name`, `flag`, `lat`, `lon`, `rank_num`, `consumption`, `cigars`, `share`, `trend`, `top_brands`, `note`, `color`, `created_at`) VALUES
  ('canada_mkt', 'Canada', '🇨🇦', '56.0000', '-96.0000', '8', '$180M/an', '~18M cigares premium/an', '~2%', 'stable', '[\"Cohiba\",\"Romeo y Julieta\",\"Davidoff\",\"Arturo Fuente\"]', 'Accès légal aux Habanos cubains contrairement aux USA. Marché sophistiqué, forte communauté de connaisseurs.', '#1A6BB5', '2026-03-18 09:43:40'),
  ('china_mkt', 'Chine', '🇨🇳', '35.0000', '105.0000', '3', '$1.2B/an', '~120M cigares premium/an', '~12%', 'forte croissance', '[\"Cohiba\",\"Davidoff\",\"Romeo y Julieta\",\"Montecristo\"]', 'Marché en explosion. Le cigare cubain symbole de statut social. Dubaï et Hong Kong hubs de distribution asiatique.', '#1A6BB5', '2026-03-18 09:43:40'),
  ('eu_mkt', 'Europe Occ.', '🇪🇺', '50.5000', '10.0000', '2', '$2.1B/an', '~280M cigares/an', '~21%', 'croissance', '[\"Cohiba\",\"Davidoff\",\"Montecristo\",\"Romeo y Julieta\",\"Café Crème\"]', 'Seul marché où les Habanos cubains sont librement vendus. France, Allemagne, Suisse, Espagne en tête. Forte culture du cigare.', '#1A6BB5', '2026-03-18 09:43:40'),
  ('france_mkt', 'France', '🇫🇷', '46.5000', '2.5000', '9', '$160M/an', '~15M cigares premium/an', '~1.6%', 'stable', '[\"Cohiba\",\"Davidoff\",\"Romeo y Julieta\",\"Montecristo\",\"Café Crème\"]', 'Altadis (Seita) distributeur Habanos exclusif en France. Forte culture bar à cigares parisien. Loi Evin contraignante.', '#1A6BB5', '2026-03-18 09:43:40'),
  ('japan_mkt', 'Japon', '🇯🇵', '36.0000', '138.0000', '4', '$380M/an', '~40M cigares premium/an', '~4%', 'stable', '[\"Davidoff\",\"Cohiba\",\"Padron\",\"Arturo Fuente\"]', 'Culture du cigare très développée. Habanos Japan distributeur officiel. Réseau de caves à cigares premium dans grandes villes.', '#1A6BB5', '2026-03-18 09:43:40'),
  ('russia_mkt', 'Russie', '🇷🇺', '56.0000', '38.0000', '7', '$220M/an', '~22M cigares premium/an', '~2%', 'déclin (sanctions)', '[\"Cohiba\",\"Montecristo\",\"Romeo y Julieta\"]', 'Marché traditionnel en recul depuis 2022. Forte demande cubaine historique. Redistribution via marchés parallèles.', '#1A6BB5', '2026-03-18 09:43:40'),
  ('switz_mkt', 'Suisse', '🇨🇭', '47.0000', '8.3000', '10', '$140M/an', '~14M cigares premium/an', '~1.4%', 'croissance', '[\"Davidoff\",\"Cohiba\",\"Romeo y Julieta\"]', 'Siège mondial de Davidoff à Genève. Intertabak AG distributeur Habanos. Tradition horlogère et cigare intimement liées.', '#1A6BB5', '2026-03-18 09:43:40'),
  ('uae_mkt', 'Émirats Arabes', '🇦🇪', '24.0000', '54.0000', '5', '$290M/an', '~30M cigares premium/an', '~3%', 'forte croissance', '[\"Cohiba\",\"Davidoff\",\"Arturo Fuente\",\"Romeo y Julieta\"]', 'Dubaï hub mondial de transit et de consommation luxury. Clientèle internationale ultra-premium. Croissance +15%/an.', '#1A6BB5', '2026-03-18 09:43:40'),
  ('uk_mkt', 'Royaume-Uni', '🇬🇧', '52.0000', '-1.5000', '6', '$260M/an', '~28M cigares premium/an', '~3%', 'stable', '[\"Romeo y Julieta\",\"Cohiba\",\"Montecristo\",\"Davidoff\"]', 'Hunters & Frankau — distributeur Habanos historique depuis 1790. Clubs londonniens (Davidoff of London) références mondiales.', '#1A6BB5', '2026-03-18 09:43:40'),
  ('usa_mkt', 'États-Unis', '🇺🇸', '38.0000', '-97.0000', '1', '$3.5B/an', '~350M cigares premium/an', '~35%', 'stable', '[\"Macanudo\",\"Rocky Patel\",\"Padron\",\"My Father\",\"Arturo Fuente\"]', 'Premier marché mondial. Embargo cubain depuis 1962 — seuls les non-cubains autorisés. Heartland des boutiques spécialisées.', '#1A6BB5', '2026-03-18 09:43:40');
