INSERT INTO `habanos_presence` (`country_id`, `present`, `status`, `status_color`, `founded`, `ownership`, `hq`, `ceo`, `revenue`, `employees`, `factories`, `marques_officielles`, `distributeurs`, `description`, `festival`, `certifications`) VALUES
  ('brazil', '0', 'PRODUCTEUR NATIONAL HISTORIQUE', '#B8860B', '1873 (Dannemann)', 'Principalement Dannemann Cigarrenfabrik (groupe suisse)', 'São Gonçalo dos Campos, Bahia, Brésil', 'Groupe Dannemann (Suisse)', '~$120M USD (feuilles + cigares)', '5 000+ (secteur tabac Bahia)', '[{\"name\":\"Dannemann Cigarrenfabrik\",\"city\":\"São Félix da Cachoeira\",\"founded\":\"1873\",\"marques\":[\"Dannemann Moods\",\"Speciale\",\"Sumatra\"]},{\"name\":\"Suerdieck\",\"city\":\"Maragogipe\",\"founded\":\"1929\",\"marques\":[\"Suerdieck Cigarros\",\"Mata Fina raw export\"]}]', '[\"Dannemann\",\"Suerdieck\"]', '[{\"pays\":\"Europe\",\"distributeur\":\"Dannemann GmbH (Allemagne/Suisse)\"},{\"pays\":\"Monde entier\",\"distributeur\":\"Export feuilles Mata Fina vers manufactures premium\"}]', 'Le Brésil n\'a pas de représentation Habanos. Son influence mondiale repose sur le tabac Mata Fina de Bahia — le meilleur wrapper Maduro naturel du monde. Des marques comme Arturo Fuente Añejo, Padrón 1926 Maduro et CAO utilisent ce wrapper exclusivement. Domestiquement, Dannemann (marque nationale) est distribuée dans 80+ pays.', 'Salon du Tabac de Bahia — annuel', '[\"MAPA (Ministère de l\'Agriculture brésilien)\",\"AFUBRA (Association des planteurs)\"]'),
  ('cameroon', '0', 'PRODUCTEUR DE WRAPPER EXCLUSIF', '#B8860B', 'Culture commerciale depuis 1910 (ère coloniale)', 'SCTC (Société Camerounaise du Tabac) + BAT Cameroun', 'Mungo, Cameroun', 'SCTC (actionnaire majoritaire : État camerounais)', '~$45M USD exportations wrapper', '3 000+ (saison de récolte)', '[{\"name\":\"SCTC — Domaine du Mont Cameroun\",\"city\":\"Mungo / Wouri\",\"founded\":\"1952\",\"marques\":[\"Wrapper Cameroon Shade exporté mondialement\"]}]', '[]', '[{\"pays\":\"USA\",\"distributeur\":\"General Cigar (contrat exclusif wrapper)\"},{\"pays\":\"Europe\",\"distributeur\":\"Scandinavian Tobacco Group\"}]', 'Le Cameroun ne possède pas de représentation Habanos et ne produit aucun cigare fini pour le marché international. Son unique contribution — mais elle est fondamentale — est le wrapper Cameroon, cultivé sur les flancs volcaniques du Mont Cameroun. Ce wrapper est parmi les plus recherchés au monde, utilisé notamment dans les Arturo Fuente Hemingway et les Oliva Serie G. La production est très limitée et fluctue selon les saisons des pluies.', 'Aucun festival cigar national', '[\"Certificat origine SCTC\",\"Contrôle phytosanitaire MINADER\"]'),
  ('cuba', '1', 'SIÈGE SOCIAL', '#C0401A', '1994 (successeur de Cubatabaco, fondé 1962)', 'État cubain (50%) + Imperial Brands PLC (50%)', 'La Havane, Cuba', 'Luis Sánchez-Harguindey Pardo de Vera', '~$500M USD annuels', '30 000+ (planteurs inclus)', '[{\"name\":\"El Laguito\",\"city\":\"La Havane\",\"founded\":\"1966\",\"marques\":[\"Cohiba\",\"Trinidad\"]},{\"name\":\"H. Upmann (Partagás)\",\"city\":\"La Havane\",\"founded\":\"1845\",\"marques\":[\"Partagás\",\"H. Upmann\",\"Bolivar\",\"Punch\",\"Ramón Allones\"]},{\"name\":\"Romeo y Julieta\",\"city\":\"La Havane\",\"founded\":\"1875\",\"marques\":[\"Romeo y Julieta\",\"Cuaba\",\"Quintero\",\"Belinda\"]},{\"name\":\"Francisco Donatién\",\"city\":\"Pinar del Río\",\"founded\":\"1961\",\"marques\":[\"Vegas Robaina\",\"Vegueros\"]},{\"name\":\"La Corona\",\"city\":\"La Havane\",\"founded\":\"1934\",\"marques\":[\"Montecristo\",\"Por Larrañaga\",\"Saint Luis Rey\"]}]', '[\"Cohiba\",\"Montecristo\",\"Partagás\",\"Romeo y Julieta\",\"H. Upmann\",\"Bolivar\",\"Trinidad\",\"Punch\",\"Diplomaticos\",\"San Cristóbal\",\"Cuaba\",\"Vegas Robaina\",\"Por Larrañaga\",\"Quintero\",\"Vegueros\",\"Ramón Allones\",\"Saint Luis Rey\"]', '[{\"pays\":\"Espagne\",\"distributeur\":\"Tabacalera S.A.U.\"},{\"pays\":\"France\",\"distributeur\":\"Altadis (Seita)\"},{\"pays\":\"Allemagne\",\"distributeur\":\"Arnold André / Habanos Deutschland\"},{\"pays\":\"Suisse\",\"distributeur\":\"Intertabak AG\"},{\"pays\":\"Royaume-Uni\",\"distributeur\":\"Hunters & Frankau\"},{\"pays\":\"Italie\",\"distributeur\":\"MST Srl\"},{\"pays\":\"Mexique\",\"distributeur\":\"Mardini Hermanos\"},{\"pays\":\"Japon\",\"distributeur\":\"Habanos Japan\"}]', 'Habanos S.A. est la plus grande société de distribution de cigares premium au monde. Elle commercialise l\'ensemble des marques cubaines à l\'international et contrôle l\'appellation d\'origine protégée \"Habanos\". L\'entreprise organise chaque année le Festival del Habano à La Havane — l\'événement mondial de référence pour les amateurs de cigares.', 'Festival del Habano — chaque février à La Havane (depuis 1999)', '[\"Denominación de Origen Protegida \\\"Habanos\\\"\",\"ISO 9001\",\"Cahier des charges plantation Vuelta Abajo\"]'),
  ('dominican', '1', 'PREMIER EXPORTATEUR MONDIAL', '#C0401A', 'Industrie installée 1960s–1970s', 'Manufactures familiales et groupes internationaux', 'Santiago de los Caballeros, Rép. Dominicaine', 'Carlos Fuente Jr. (A. Fuente), Ernst Schneider (Davidoff), Litto Gomez (LFD)…', '~$1.2B USD exportations annuelles (record mondial)', '35 000+ (secteur tabac)', '[{\"name\":\"Tabacalera A. Fuente & Cia\",\"city\":\"Santiago\",\"founded\":\"1980\",\"marques\":[\"Opus X\",\"Hemingway\",\"Añejo\",\"Don Carlos\",\"Cuesta Rey\"]},{\"name\":\"Manufactura de Tabacos S.A. (MATASA)\",\"city\":\"Santiago\",\"founded\":\"1967\",\"marques\":[\"Avo\",\"Davidoff\",\"Juan Clemente\",\"Zino Platinum\"]},{\"name\":\"La Flor Dominicana S.A.\",\"city\":\"Santiago\",\"founded\":\"1996\",\"marques\":[\"LFD Double Ligero\",\"Air Bender\",\"Cameroon Especiale\"]},{\"name\":\"General Cigar Dominicana\",\"city\":\"La Romana\",\"founded\":\"1968\",\"marques\":[\"Macanudo\",\"Punch DOM\",\"Partagás DOM\"]},{\"name\":\"Consolidated Cigar Corp.\",\"city\":\"Santiago\",\"founded\":\"1970\",\"marques\":[\"H. Upmann DOM\",\"Romeo y Julieta DOM\",\"Montecristo White\"]}]', '[\"Arturo Fuente\",\"Davidoff\",\"La Flor Dominicana\",\"Macanudo\",\"Ashton\",\"Avo\",\"Romeo y Julieta (DOM)\",\"H. Upmann (DOM)\",\"Cubao\",\"La Gloria Cubana (DOM)\"]', '[{\"pays\":\"USA\",\"distributeur\":\"General Cigar Co. / Altadis USA / STG\"},{\"pays\":\"Europe\",\"distributeur\":\"Oettinger Davidoff AG / Scandinavian Tobacco\"},{\"pays\":\"Monde entier\",\"distributeur\":\"90+ importateurs agréés\"}]', 'La République Dominicaine est le premier exportateur mondial de cigares en valeur. La région de Santiago abrite une concentration unique de manufactures de premier plan. L\'appellation \"Cibao\" pour le tabac dominicain est reconnue internationalement. Le pays produit des cigares pour presque toutes les grandes marques mondiales.', 'ProCigar Festival — chaque février à Santiago (depuis 2006)', '[\"Denominación de Origen \\\"Cibao\\\"\",\"ProCigar (Association des fabricants dominicains)\",\"DICOEX export certification\"]'),
  ('ecuador', '0', 'FOURNISSEUR MONDIAL DE WRAPPER', '#B8860B', 'Culture développée 1970s–1980s', 'Plantations de manufactures étrangères (Plasencia, General Cigar, STG)', 'Los Ríos / Guayas, Équateur', 'N/A — principalement culture de feuilles brutes', '~$180M USD exportations feuilles', '8 000+ (secteur agricole)', '[{\"name\":\"Plasencia Ecuador\",\"city\":\"Los Ríos\",\"founded\":\"1990s\",\"marques\":[\"Fournisseur universel de wrapper\"]},{\"name\":\"CETABACO\",\"city\":\"Guayas\",\"founded\":\"1980s\",\"marques\":[\"Connecticut Shade Ecuador\",\"Ecuador Habano\"]},{\"name\":\"General Cigar Ecuador\",\"city\":\"Los Ríos\",\"founded\":\"1990s\",\"marques\":[\"Wrapper pour Macanudo, CAO, Partagás…\"]}]', '[]', '[{\"pays\":\"Monde entier\",\"distributeur\":\"Export de feuilles brutes vers manufactures USA/RD/Nicaragua\"}]', 'L\'Équateur n\'a pas de représentation Habanos et ne produit pas de cigares finis sous sa propre marque — il est exclusivement un fournisseur mondial de feuilles de wrapper. La couverture nuageuse naturelle de la région remplace l\'ombrage artificiel utilisé au Connecticut, produisant un wrapper Connecticut Shade de qualité identique à moindre coût. Presque toutes les grandes manufactures mondiales utilisent du wrapper équatorien.', 'Aucun festival cigar national', '[\"Certificat phytosanitaire AGROCALIDAD\",\"PROECUADOR export label\"]'),
  ('honduras', '1', 'REPRÉSENTATION RÉGIONALE', '#B8860B', 'Industrie établie 1960s', 'HATSA (Honduras American Tobacco S.A.) + indépendants', 'Danlí, Honduras', 'Multiple — Alan Rubin (Alec Bradley), Cano Ozgener legacy (CAO)…', '~$220M USD exportations annuelles', '12 000+ (secteur tabac)', '[{\"name\":\"HATSA\",\"city\":\"Danlí\",\"founded\":\"1968\",\"marques\":[\"Hoyo de Monterrey HN\",\"Punch HN\",\"Excalibur\"]},{\"name\":\"Raices Cubanas S.A.\",\"city\":\"Danlí\",\"founded\":\"1990s\",\"marques\":[\"Alec Bradley Prensado\",\"Black Market\",\"Tempus\"]},{\"name\":\"Tabacos Rancho Jamastran\",\"city\":\"Jamastran\",\"founded\":\"1962\",\"marques\":[\"Camacho Corojo\",\"Triple Maduro\",\"American Barrel-Aged\"]},{\"name\":\"STG Honduras (Altadis)\",\"city\":\"Danlí\",\"founded\":\"1980s\",\"marques\":[\"CAO\",\"Baccarat\",\"Henri Wintermans HN\"]}]', '[\"Alec Bradley\",\"CAO Honduras\",\"Camacho\",\"Punch (HN)\",\"Hoyo de Monterrey (HN)\",\"Baccarat\",\"Excalibur\"]', '[{\"pays\":\"USA\",\"distributeur\":\"Altadis USA / General Cigar / STG\"},{\"pays\":\"Europe\",\"distributeur\":\"Scandinavian Tobacco Group\"}]', 'Le Honduras est le quatrième producteur mondial de cigares premium. La Vallée de Jamastran, à 900m d\'altitude, produit certains des tabacs Corojo les plus puissants hors de Cuba. L\'industrie hondurienne est largement contrôlée par des groupes américains et européens.', 'Salon de tabac — intégré aux foires régionales d\'Amérique Centrale', '[\"Denominación de Origen \\\"Jamastran\\\"\",\"Honduras Cigar Association (HCA)\"]'),
  ('indonesia', '0', 'FOURNISSEUR DE WRAPPER SUMATRA', '#B8860B', 'Culture commerciale Deli Sumatra depuis 1863', 'PT Djarum / PT Gudang Garam / PT Sadhana Arif Nusa', 'Medan, Sumatra Nord, Indonésie', 'Multiple — conglomérats locaux', '~$220M USD exportations feuilles', '20 000+ (secteur plantation)', '[{\"name\":\"PT Sadhana Arif Nusa\",\"city\":\"Deli, Sumatra Nord\",\"founded\":\"1977\",\"marques\":[\"Deli Sumatra Wrapper — export cigarillos Europe\"]},{\"name\":\"PT Djarum\",\"city\":\"Kudus, Java\",\"founded\":\"1951\",\"marques\":[\"Djarum Black\",\"La Finca Cigars\"]}]', '[\"Café Crème\",\"Henri Wintermans\",\"Agio\"]', '[{\"pays\":\"Europe\",\"distributeur\":\"Royal Agio Cigars (Pays-Bas)\"},{\"pays\":\"Monde entier\",\"distributeur\":\"Export wrapper brut vers 40+ manufactures\"}]', 'L\'Indonésie ne possède pas de représentation Habanos. Sa contribution principale est le wrapper Deli Sumatra, cultivé sur des sols volcaniques depuis les plantations hollandaises du XIXème siècle. Ce wrapper — terreux, légèrement épicé — est l\'un des plus utilisés pour les cigarillos et cigares milieu de gamme en Europe.', 'Aucun festival cigar international', '[\"Badan Karantina (quarantaine agricole)\",\"Export license Kementerian Pertanian\"]'),
  ('mexico', '0', 'NICHE PREMIUM — WRAPPER SAN ANDRÉS', '#3D6B4A', '1963 (Te Amo / famille Turrent)', 'Famille Turrent (Tabacos San Andrés)', 'San Andrés Tuxtla, Veracruz, Mexique', 'Famille Turrent (4ème génération)', '~$85M USD exportations', '2 000+', '[{\"name\":\"Tabacos San Andrés S.A.\",\"city\":\"San Andrés Tuxtla\",\"founded\":\"1963\",\"marques\":[\"Te Amo\",\"Santa Clara 1830\",\"export wrapper San Andrés\"]},{\"name\":\"Hoja de México\",\"city\":\"Los Tuxtlas\",\"founded\":\"2000s\",\"marques\":[\"CAO Black wrapper\",\"Onyx wrapper\"]}]', '[\"Te Amo\",\"Santa Clara 1830\",\"Onyx\"]', '[{\"pays\":\"USA\",\"distributeur\":\"Te Amo USA / General Cigar\"},{\"pays\":\"Monde entier\",\"distributeur\":\"Export wrapper San Andrés Maduro Negro\"}]', 'Le Mexique n\'a pas de représentation Habanos mais détient un terroir unique avec les \"terres noires\" volcaniques de San Andrés Tuxtla. Le wrapper San Andrés Maduro Negro est le plus naturellement foncé du monde — il fermente naturellement sans additifs, développant une douceur et une onctuosité incomparables. La famille Turrent contrôle l\'essentiel de la production depuis 4 générations.', 'Aucun festival cigar international', '[\"Denominación de Origen \\\"San Andrés Tuxtla\\\"\",\"SAGARPA Mexico\"]'),
  ('nicaragua', '1', 'PÔLE MONDIAL INDÉPENDANT', '#C0401A', 'Industrie développée 1960s–1990s', 'Principalement manufactures familiales indépendantes', 'Estelí, Nicaragua', 'Multiple — Jorge Padrón (Padrón), Janny Garcia (My Father), Willy Herrera (Drew Estate)…', '~$850M USD exportations annuelles', '25 000+ (secteur tabac)', '[{\"name\":\"Tabacos Valle de Jalapa (TAVASA)\",\"city\":\"Jalapa\",\"founded\":\"1970s\",\"marques\":[\"Padrón 1926\",\"Padrón 1964\",\"Family Reserve\"]},{\"name\":\"My Father Cigars S.A.\",\"city\":\"Estelí\",\"founded\":\"2006\",\"marques\":[\"My Father\",\"Le Bijou 1922\",\"Flor de Las Antillas\"]},{\"name\":\"Plasencia Cigars S.A.\",\"city\":\"Estelí\",\"founded\":\"1970s\",\"marques\":[\"Plasencia Cosecha\",\"Alma del Fuego\",\"Reserva Original\"]},{\"name\":\"Drew Estate S.A.\",\"city\":\"Estelí\",\"founded\":\"1999\",\"marques\":[\"Liga Privada No.9\",\"T52\",\"Acid\",\"Herrera Estelí\"]},{\"name\":\"Oliva Cigar Co.\",\"city\":\"Estelí\",\"founded\":\"1995\",\"marques\":[\"Serie V\",\"Melanio\",\"Serie G\"]}]', '[\"Padrón\",\"My Father\",\"Oliva\",\"Drew Estate\",\"Plasencia\",\"Rocky Patel\",\"Perdomo\",\"Joya de Nicaragua\",\"AJ Fernandez\",\"Mombacho\",\"La Flor de Selva\"]', '[{\"pays\":\"USA\",\"distributeur\":\"Distribution directe (marchés spécialisés)\"},{\"pays\":\"Europe\",\"distributeur\":\"Altadis / Scandinavian Tobacco Group\"},{\"pays\":\"Canada\",\"distributeur\":\"Imperial Tobacco Canada\"}]', 'Le Nicaragua est devenu le premier producteur mondial de cigares premium en volume, dépassant Cuba et la République Dominicaine. L\'industrie se concentre autour d\'Estelí — la \"Capitale du Cigare\" — où se trouvent les manufactures des plus grandes maisons. Contrairement à Cuba, l\'industrie nicaraguayenne est entièrement privée et très compétitive.', 'Nicaragua Cigars Event — festival annuel à Estelí', '[\"Denominación de Origen \\\"Jalapa\\\"\",\"Denominación de Origen \\\"Estelí\\\"\",\"CAAN (Cámara Nicaragüense de Tabaco)\"]'),
  ('panama', '0', 'TERROIR ÉMERGENT', '#3D6B4A', 'Production premium lancée ~2000', 'Toraño Panama / El Hatillo (petites structures)', 'Chiriquí, Panama', 'Carlos Toraño (pionnier)', '~$12M USD', '500+', '[{\"name\":\"Toraño Panama\",\"city\":\"Volcán, Chiriquí\",\"founded\":\"2001\",\"marques\":[\"Carlos Toraño Exodus 1959\",\"Toraño Signature\"]}]', '[\"Carlos Toraño Panama\",\"La Palina Panama\"]', '[{\"pays\":\"USA\",\"distributeur\":\"Distribution directe boutiques spécialisées\"}]', 'Le Panama n\'a pas de représentation Habanos. Son terroir volcanique de Chiriquí, à 1400m d\'altitude sur les flancs du Volcán Barú, est l\'un des plus prometteurs d\'Amérique Centrale. Les conditions climatiques — altitude, sol volcanique, hygrométrie — y créent un microclimate exceptionnel. L\'industrie est encore très artisanale et en développement.', 'Aucun festival cigar national', '[\"MIDA Panama (agriculture)\"]'),
  ('philippines', '0', 'PRODUCTION HISTORIQUE', '#3D6B4A', '1782 (Tabacalera — monopole espagnol)', 'PMFTC (Philip Morris) + Tabacalera Philippines', 'Manille, Philippines', 'Multiple', '~$35M USD', '8 000+ (secteur tabac)', '[{\"name\":\"Tabacalera Philippines\",\"city\":\"Manille\",\"founded\":\"1782\",\"marques\":[\"Tabacalera Pilipinas\",\"Tabacalera Special Reserve\"]},{\"name\":\"La Flor de la Isabela\",\"city\":\"Isabela\",\"founded\":\"1960s\",\"marques\":[\"Purito Filipino\",\"La Flor artisanal\"]}]', '[\"Tabacalera\",\"La Flor de la Isabela\"]', '[{\"pays\":\"Philippines\",\"distributeur\":\"Marché domestique principalement\"},{\"pays\":\"Espagne\",\"distributeur\":\"Tabacalera España (liens historiques)\"}]', 'Les Philippines ne possèdent pas de représentation Habanos. L\'une des plus anciennes industries du tabac au monde (monopole espagnol depuis 1782), elle est aujourd\'hui sous-exploitée à l\'international. Le terroir de la Cagayan Valley a un réel potentiel premium qui reste largement inexploité. Le marché est principalement domestique.', 'Aucun festival cigar international', '[\"BPI Philippines (Bureau of Plant Industry)\",\"FDA Philippines\"]'),
  ('usa', '0', 'MARCHÉ ET PRODUCTEUR DE WRAPPER', '#B8860B', 'Culture sous voile depuis 1900 (Connecticut)', 'Swedish Match / Altadis USA / General Cigar', 'Richmond, Virginie (General Cigar HQ)', 'Peter Jung (Scandinavian Tobacco Group Americas)', '~$380M USD marché premium local', '15 000+ (industrie tabac Connecticut)', '[{\"name\":\"General Cigar Richmond\",\"city\":\"Richmond, VA\",\"founded\":\"1906\",\"marques\":[\"Macanudo\",\"Punch DOM\",\"CAO\"]},{\"name\":\"Altadis USA\",\"city\":\"Fort Lauderdale, FL\",\"founded\":\"1999 (fusion)\",\"marques\":[\"H. Upmann DOM\",\"Romeo y Julieta DOM\",\"Montecristo White\"]},{\"name\":\"Drew Estate (Swisher)\",\"city\":\"Jacksonville, FL\",\"founded\":\"1996\",\"marques\":[\"Liga Privada\",\"Acid\",\"Herrera Estelí\"]}]', '[\"General Cigar Portfolio\",\"Altadis USA Portfolio\"]', '[{\"pays\":\"USA\",\"distributeur\":\"Marché domestique — réseau de détaillants agréés nationwide\"}]', 'Les États-Unis sont le plus grand marché consommateur de cigares premium au monde. Le Connecticut Shade — cultivé sous voiles dans la Vallée du Connecticut depuis 1900 — est le wrapper le plus doux au monde, utilisé par Macanudo, Davidoff, Ashton et des dizaines d\'autres. L\'embargo sur Cuba (1962) a paradoxalement boosté les industries nicaraguayenne et dominicaine qui ont absorbé les maîtres torcedores cubains exilés.', 'IPCPR Trade Show (Big Smoke) — Las Vegas, annuel', '[\"FDA (Food and Drug Administration) — réglementation tabac\",\"USTC (United States Tobacco Council)\"]');
INSERT INTO `brands` (`name`, `country_id`, `founded`, `history`, `gamme`, `created_at`, `updated_at`, `scores`, `celebrities`, `pairings`, `limited_eds`, `factory`, `history_en`, `history_es`, `history_de`, `history_zh`, `history_ar`, `gamme_en`, `gamme_es`, `notes_en`, `notes_es`, `notes_de`, `notes_zh`, `notes_ar`, `gamme_de`, `gamme_zh`, `gamme_ar`, `celebrities_en`, `celebrities_es`, `celebrities_de`, `celebrities_zh`, `celebrities_ar`, `pairings_en`, `pairings_es`, `pairings_de`, `pairings_zh`, `pairings_ar`) VALUES
  ('Cohiba', '🇨🇺 Cuba', '1966 — La Havane, Cuba', 'Cohiba naquit dans le plus grand secret pour servir Fidel Castro. Eduardo Rivera, torcedor remarqué par un garde du corps de Castro pour la qualité extraordinaire de ses cigares personnels, fut convoqué à La Havane. Pendant seize ans, Cohiba ne fut jamais commercialisée — uniquement offerte comme cadeau diplomatique aux chefs d\'État du monde entier : Brandt, Mitterrand, Gaddafi reçurent tous des boîtes de ce cigare sans nom.\r\n\r\nEn 1982, face à la demande diplomatique croissante, Cuba décida d\'ouvrir Cohiba au commerce international. Le nom vient du mot Taïno — la langue des premiers habitants de Cuba — désignant le tabac. Cohiba est aujourd\'hui la marque de cigares la plus reconnue, la plus copiée et la plus convoitée du monde. Ses feuilles proviennent exclusivement de la région Vuelta Abajo, la plus prestigieuse de Cuba, et subissent une troisième fermentation supplémentaire qui n\'existe nulle part ailleurs.\r\n\r\nLa manufacture El Laguito, nichée dans un ancien hôtel particulier havanais, est le sanctuaire de la marque. Ses torcedoras — majoritairement des femmes — sont les artisanes les mieux payées de Cuba. On dit que fumer un Cohiba, c\'est inhaler six décennies d\'histoire révolutionnaire.', '[\r\n  {\"name\":\"Behike BHK\",\"color\":\"#8B0000\",\"story\":\"Lancée en 2010 pour les 44 ans de la marque, la Behike est la vitola la plus rare et la plus chère de l\'histoire cubaine. Elle utilise la rarissime feuille medio tiempo — poussant au sommet du plant tabacalero, trop petite pour être récoltée à grande échelle. Trois formats seulement, quelques milliers de boîtes par an. Score parfait par plusieurs experts. Prix unitaire : 30 à 50€.\",\"force\":\"Full\",\"wrapper\":\"Habano Colorado\",\"vitolas\":[\"BHK 52\",\"BHK 54\",\"BHK 56\"],\"scores\":[{\"source\":\"Cigar Aficionado\",\"score\":98,\"year\":2011},{\"source\":\"Cigar Journal\",\"score\":97,\"year\":2012}]},\r\n  {\"name\":\"Línea 1492\",\"color\":\"#C04000\",\"story\":\"Créée pour le 500ème anniversaire de la découverte des Amériques en 1992. Les Sublimes EL et Pirámides comptent parmi les vitolas les plus rares de la maison. Disponibles en éditions régionales dans certains pays seulement. La Línea 1492 incarne la Cohiba de luxe quotidien — full body sans excès.\",\"force\":\"Medium-Full\",\"wrapper\":\"Habano Colorado Claro\",\"vitolas\":[\"Sublimes\",\"Pirámides\",\"Robusto Extra\",\"Coronas Especiales\"]},\r\n  {\"name\":\"Siglo I–VI\",\"color\":\"#8B6914\",\"story\":\"Les Clásicos — gamme originelle de Castro. Les Siglo progressent de I à VI en longueur et intensité. Le Lancero (Siglo VI allongé) reste le test ultime de tout torcedor cubain. Difficile à rouler parfaitement, difficile à fumer parfaitement. La bague dorée et sa bande noire sont devenues le symbole universel du cigare de prestige.\",\"force\":\"Medium\",\"wrapper\":\"Habano Claro\",\"vitolas\":[\"Siglo I\",\"Siglo II\",\"Siglo III\",\"Siglo IV\",\"Siglo V\",\"Siglo VI\"]},\r\n  {\"name\":\"Maduro 5\",\"color\":\"#3D1C00\",\"story\":\"Lancée en 2007, première Maduro dans l\'univers cubain — une révolution. Wrapper maduro vieilli 5 ans en fûts supplémentaires, créant une douceur paradoxale malgré la puissance. Notes de pruneaux, chocolat noir, café torréfié. Les fumeurs habitués aux cubains traditionnels furent déstabilisés par cette douceur inattendue. Aujourd\'hui culte.\",\"force\":\"Medium-Full\",\"wrapper\":\"Habano Maduro x5\",\"vitolas\":[\"Genios\",\"Mágicos\",\"Secretos\",\"Divinos\"]},\r\n  {\"name\":\"Serie D\",\"color\":\"#5C1A00\",\"story\":\"La Robaina — format Robusto (50 x 124mm), format roi. Fumée en 45 minutes, la Serie D No.4 est la référence mondiale du Robusto. Densément chargée, elle libère en milieu de fumée une complexité épicée unique. Indispensable dans toute cave sérieuse.\",\"force\":\"Full\",\"wrapper\":\"Habano Colorado\",\"vitolas\":[\"No.4\",\"No.5\",\"No.6\"]}\r\n]', '2026-03-18 09:43:40', '2026-03-22 15:12:47', '[{\"source\":\"Cigar Aficionado\",\"score\":97,\"year\":2023,\"vitola\":\"Siglo VI\"},{\"source\":\"Cigar Aficionado\",\"score\":98,\"year\":2011,\"vitola\":\"Behike BHK 56\"}]', '[{\"name\":\"Fidel Castro\",\"anecdote\":\"Castro fumait 20 à 25 Cohiba par jour avant d\'arrêter en 1985 sur conseil médical. Il aurait déclaré : \'La meilleure chose que j\'ai faite pour ma santé, c\'est d\'arrêter de fumer. La meilleure chose que j\'ai faite pour mes ennemis, c\'est de continuer à leur en offrir.\'\"},{\"name\":\"Jack Nicholson\",\"anecdote\":\"Fumeur notoire de Cohiba Esplendidos lors de ses apparitions aux Oscars, contribuant à populariser la marque aux États-Unis malgré l\'embargo.\"},{\"name\":\"Che Guevara\",\"anecdote\":\"Figure iconique du cigare cubain, souvent photographié avec un Cohiba. L\'image est devenue un symbole culturel mondial.\"}]', '[{\"type\":\"Spiritueux\",\"name\":\"Cognac Hennessy XO\",\"notes\":\"La rondeur du cognac amplifie les notes boisées du Behike. Accord classique des grandes occasions.\"},{\"type\":\"Rhum\",\"name\":\"Ron Santiago de Cuba 12 ans\",\"notes\":\"L\'accord naturel — les deux produits partagent les mêmes terres cubaines. Notes de canne et de tabac en résonance.\"},{\"type\":\"Café\",\"name\":\"Café cubain cortadito\",\"notes\":\"L\'amertume douce du café cubain soutient parfaitement la complexité épicée d\'un Siglo III après repas.\"}]', '[\"Cohiba Behike BHK 52/54/56 (2010)\",\"Cohiba 55 Aniversario (2021)\",\"Cohiba Sublimes EL (annuel)\",\"Cohiba 1966 EL\",\"Cohiba Siglo VI Gran Reserva Cosecha 2006\"]', 'El Laguito, La Havane — manufacture exclusive Cohiba', 'Cohiba was born in absolute secrecy in 1966. Eduardo Rivera, a torcedor whose exceptional private cigars had caught the eye of a presidential bodyguard, was summoned to Havana and quietly installed at El Laguito — a former aristocratic mansion in the Miramar district. For sixteen years, Cohiba was never sold. It existed as a diplomatic instrument: boxes without price tags, offered by Fidel Castro to heads of state who understood immediately they held something extraordinary. Willy Brandt received them in Bonn. François Mitterrand in Paris. Muammar Gaddafi in Tripoli. Nelson Mandela in Johannesburg. All received boxes of this nameless cigar.\r\n\r\nIn 1982, facing mounting international curiosity and a growing black market, Cuba opened Cohiba to commercial distribution — but only outside the island, and only through Cubatabaco\'s most exclusive channels. The name comes from the Taíno language, spoken by Cuba\'s original inhabitants before Columbus: it simply means tobacco. The irony is perfect — the world\'s most prestigious cigar bears the most ancient and universal name for what it is.\r\n\r\nWhat makes Cohiba technically distinct is the third fermentation. After the standard two fermentations undergone by all Cuban tobacco, Cohiba\'s leaves undergo a third extended fermentation in cedar barrels. This process, closely guarded and unique in the industry, extracts a final layer of harshness and develops the complex, almost creamy equilibrium that defines the brand\'s profile. The leaves come exclusively from Vuelta Abajo, Cuba\'s most prestigious growing region, and are selected personally by the factory\'s master blenders.\r\n\r\nEl Laguito is Cohiba\'s world. Its workforce is predominantly female — the torcedoras who roll Cohiba are Cuba\'s highest-paid cigar artisans. The factory does not receive visitors. Its rhythms are its own. Each cigar leaving El Laguito passes through more quality control checkpoints than any other Cuban brand. Rejected cigars — roughly one in five — are destroyed, never redistributed.\r\n\r\nThe Cohiba band, with its distinctive black and yellow design, has become a universal symbol of status extending far beyond the tobacco world. It appears in film, literature, and political photography as shorthand for power. It is also the world\'s most counterfeited cigar band — a distinction that measures the brand\'s reach better than any sales figure.\r\n\r\nToday, Cohiba stands as the undisputed apex of Cuban tobacco. The Behike BHK line, launched in 2010 for the brand\'s 44th anniversary, pushed the concept further still: using the ultra-rare medio tiempo leaf — found only at the very crown of the tobacco plant, in quantities too small to harvest at scale — it produced what many experts consider the most complex cigar ever commercially released. Fewer than three thousand boxes exist per year. The waiting lists are longer than the cigar itself.', 'Cohiba nació en el mayor secreto para servir a Fidel Castro. Eduardo Rivera, torcedor cuyos cigarros personales habían llamado la atención de un guardaespaldas de Castro, fue convocado a La Habana. Durante dieciséis años, Cohiba nunca se comercializó — solo se ofrecía como regalo diplomático a jefes de Estado. Brandt, Mitterrand y Gaddafi recibieron cajas de este cigarro sin nombre.\r\n\r\nEn 1982, ante la creciente demanda diplomática, Cuba abrió Cohiba al comercio internacional. El nombre proviene del vocablo taíno — lengua de los primeros habitantes de Cuba — que significa tabaco. Cohiba es hoy la marca de cigarros más reconocida, más falsificada y más codiciada del mundo.\r\n\r\nLa fábrica El Laguito, ubicada en una antigua mansión habanera, es el santuario de la marca. Sus torcedoras — en su mayoría mujeres — son las artesanas del cigarro mejor pagadas de Cuba. Fumar un Cohiba es inhalar seis décadas de historia revolucionaria.', 'Cohiba wurde im strengsten Geheimnis geboren, um Fidel Castro zu dienen. Eduardo Rivera, ein Torcedor, dessen außergewöhnliche persönliche Zigarren einem Leibwächter Castros aufgefallen waren, wurde nach Havanna beordert. Sechzehn Jahre lang wurde Cohiba nie kommerziell verkauft — ausschließlich als diplomatisches Geschenk an Staatsoberhäupter überreicht. Brandt, Mitterrand und Gaddafi erhielten alle Kisten dieser namenlosen Zigarre.\r\n\r\n1982 öffnete Kuba Cohiba dem internationalen Handel. Der Name stammt aus der Taíno-Sprache — der Sprache der Ureinwohner Kubas — und bedeutet Tabak. Cohiba ist heute die weltweit bekannteste, meistgefälschte und begehrteste Zigarrenmarke.\r\n\r\nDie El Laguito Fabrik, eingebettet in eine ehemalige Havannaer Villa, ist das Heiligtum der Marke. Ihre Torcedoras — überwiegend Frauen — sind Kubas bestbezahlte Zigarrenhandwerkerinnen. Eine Cohiba zu rauchen bedeutet, sechs Jahrzehnte Revolutionsgeschichte zu inhalieren.', '科伊巴诞生于最高度保密之中，专为菲德尔·卡斯特罗服务。爱德华多·里维拉是一位雪茄卷制师，他精湛的个人雪茄引起了卡斯特罗警卫的注意，被召至哈瓦那。十六年间，科伊巴从未商业销售——仅作为外交礼物赠予各国元首。勃兰特、密特朗和卡扎菲都曾收到这种无名雪茄的礼盒。\r\n\r\n1982年，面对日益增长的外交需求，古巴决定向国际市场开放科伊巴。品牌名称来自泰诺语——古巴原住民的语言——意为烟草。科伊巴如今是全球最知名、最被仿冒、最令人垂涎的雪茄品牌。\r\n\r\n坐落在哈瓦那旧宅中的拉古尼托工厂是品牌的圣地。女卷制师们——主要为女性——是古巴薪酬最高的雪茄工匠。吸一支科伊巴，就是在吸入六十年的革命历史。', 'وُلدت كوهيبا في سرية تامة لخدمة فيدل كاسترو. إدواردو ريفيرا، ملفِّف السيجار الذي لفت سجائره الشخصية الاستثنائية انتباه أحد حراس كاسترو، استُدعي إلى هافانا. لستة عشر عامًا، لم تُطرح كوهيبا للبيع التجاري قط — بل كانت تُقدَّم هدية دبلوماسية لرؤساء الدول. برانت وميتران والقذافي جميعهم استلموا علبًا من هذا السيجار المجهول الهوية.\r\n\r\nعام 1982، وأمام الطلب الدبلوماسي المتزايد، فتحت كوبا كوهيبا أمام التجارة الدولية. يأتي الاسم من كلمة تاينو — لغة سكان كوبا الأصليين — وتعني التبغ. تُعدّ كوهيبا اليوم العلامة التجارية الأكثر شهرةً وتقليدًا وتوقًا في عالم السيجار.\r\n\r\nمصنع إل لاغونيتو، الكامن في قصر هافاني سابق، هو حرم العلامة. ملفِّفاتها — معظمهن نساء — هن أعلى حِرفيات السيجار أجرًا في كوبا. إشعال كوهيبا يعني استنشاق ستة عقود من التاريخ الثوري.', '[{\"name\": \"Behike BHK\", \"color\": \"#8B0000\", \"story\": \"Launched in 2010 for the brand\'s 44th anniversary, the Behike is the rarest and most expensive vitola in Cuban history. It uses the ultra-rare medio tiempo leaf — growing at the very top of the tobacco plant, too small to harvest at scale. Three formats only, a few thousand boxes per year. Perfect scores from multiple experts. Unit price: €30–50.\", \"force\": \"Full\", \"wrapper\": \"Habano Colorado\", \"vitolas\": [\"BHK 52\", \"BHK 54\", \"BHK 56\"], \"scores\": [{\"source\": \"Cigar Aficionado\", \"score\": 98, \"year\": 2011}]}, {\"name\": \"Línea 1492\", \"color\": \"#C04000\", \"story\": \"Created for the 500th anniversary of the Americas\' discovery in 1992. The Sublimes EL and Pirámides are among the house\'s rarest vitolas, available as regional editions in select countries only. The Línea 1492 embodies everyday luxury Cohiba — full body without excess.\", \"force\": \"Medium-Full\", \"wrapper\": \"Habano Colorado Claro\", \"vitolas\": [\"Sublimes\", \"Pirámides\", \"Robusto Extra\", \"Coronas Especiales\"]}, {\"name\": \"Siglo I–VI\", \"color\": \"#8B6914\", \"story\": \"The Clásicos — Castro\'s original range. Siglos progress from I to VI in length and intensity. The Lancero (elongated Siglo VI) remains the ultimate test for any Cuban torcedor. The gold band with its black stripe has become the universal symbol of prestige.\", \"force\": \"Medium\", \"wrapper\": \"Habano Claro\", \"vitolas\": [\"Siglo I\", \"Siglo II\", \"Siglo III\", \"Siglo IV\", \"Siglo V\", \"Siglo VI\"]}, {\"name\": \"Maduro 5\", \"color\": \"#3D1C00\", \"story\": \"Launched in 2007, the first Maduro in the Cuban universe. The wrapper is aged 5 additional years in barrels, creating paradoxical sweetness despite the power. Notes of prunes, dark chocolate, roasted coffee. Traditional Cuban smokers were unsettled by this unexpected softness. Now iconic.\", \"force\": \"Medium-Full\", \"wrapper\": \"Habano Maduro x5\", \"vitolas\": [\"Genios\", \"Mágicos\", \"Secretos\", \"Divinos\"]}, {\"name\": \"Serie D\", \"color\": \"#5C1A00\", \"story\": \"The Robaina — Robusto format (50 x 124mm), king of formats. The Serie D No.4 is the world\'s reference Robusto. Densely packed, it releases a unique spiced complexity mid-smoke. Essential in any serious humidor.\", \"force\": \"Full\", \"wrapper\": \"Habano Colorado\", \"vitolas\": [\"No.4\", \"No.5\", \"No.6\"]}]', '[{\"name\": \"Behike BHK\", \"color\": \"#8B0000\", \"story\": \"Lanzada en 2010 para el 44º aniversario de la marca, la Behike es la vitola más rara y costosa de la historia cubana. Utiliza la rarísima hoja medio tiempo — que crece en la cima de la planta de tabaco, demasiado pequeña para cosechar a escala. Solo tres formatos, unos pocos miles de cajas al año. Puntuaciones perfectas de múltiples expertos. Precio unitario: 30-50€.\", \"force\": \"Full\", \"wrapper\": \"Habano Colorado\", \"vitolas\": [\"BHK 52\", \"BHK 54\", \"BHK 56\"], \"scores\": [{\"source\": \"Cigar Aficionado\", \"score\": 98, \"year\": 2011}]}, {\"name\": \"Línea 1492\", \"color\": \"#C04000\", \"story\": \"Creada para el 500º aniversario del descubrimiento de América en 1992. Los Sublimes EL y Pirámides están entre las vitolas más raras de la casa, disponibles solo como ediciones regionales en países seleccionados. La Línea 1492 encarna el lujo cotidiano de Cohiba — cuerpo completo sin exceso.\", \"force\": \"Medium-Full\", \"wrapper\": \"Habano Colorado Claro\", \"vitolas\": [\"Sublimes\", \"Pirámides\", \"Robusto Extra\", \"Coronas Especiales\"]}, {\"name\": \"Siglo I–VI\", \"color\": \"#8B6914\", \"story\": \"Los Clásicos — la gama original de Castro. Los Siglos progresan del I al VI en longitud e intensidad. El Lancero (Siglo VI alargado) sigue siendo la prueba definitiva de todo torcedor cubano. La banda dorada con su franja negra se ha convertido en el símbolo universal del prestigio.\", \"force\": \"Medium\", \"wrapper\": \"Habano Claro\", \"vitolas\": [\"Siglo I\", \"Siglo II\", \"Siglo III\", \"Siglo IV\", \"Siglo V\", \"Siglo VI\"]}, {\"name\": \"Maduro 5\", \"color\": \"#3D1C00\", \"story\": \"Lanzada en 2007, la primera Maduro en el universo cubano — una revolución. La envolvente Maduro se añeja 5 años adicionales en barricas, creando una dulzura paradójica a pesar del poder. Notas de ciruela, chocolate negro, café tostado. Actualmente icónica.\", \"force\": \"Medium-Full\", \"wrapper\": \"Habano Maduro x5\", \"vitolas\": [\"Genios\", \"Mágicos\", \"Secretos\", \"Divinos\"]}, {\"name\": \"Serie D\", \"color\": \"#5C1A00\", \"story\": \"El Robaina — formato Robusto (50 x 124mm), rey de los formatos. Bien apretada, libera a mitad de fumada una inesperada complejidad especiada. Imprescindible en cualquier humidor serio.\", \"force\": \"Full\", \"wrapper\": \"Habano Colorado\", \"vitolas\": [\"No.4\", \"No.5\", \"No.6\"]}]', NULL, NULL, NULL, NULL, NULL, '[{\"name\": \"Behike BHK\", \"color\": \"#8B0000\", \"story\": \"Zum 44. Jubiläum 2010 lanciert, ist die Behike die seltenste und teuerste Vitola der kubanischen Geschichte. Sie verwendet das ultrararere Medio-Tiempo-Blatt — das an der Spitze der Tabakpflanze wächst, zu klein für die Ernte. Nur drei Formate, einige tausend Kisten pro Jahr. Perfekte Bewertungen von mehreren Experten. Stückpreis: 30-50€.\", \"force\": \"Full\", \"wrapper\": \"Habano Colorado\", \"vitolas\": [\"BHK 52\", \"BHK 54\", \"BHK 56\"], \"scores\": [{\"source\": \"Cigar Aficionado\", \"score\": 98, \"year\": 2011}]}, {\"name\": \"Línea 1492\", \"color\": \"#C04000\", \"story\": \"Zum 500. Jahrestag der Entdeckung Amerikas 1992 geschaffen. Die Sublimes EL und Pirámides gehören zu den seltensten Vitolas des Hauses, nur als Regionaleditionen in ausgewählten Ländern erhältlich.\", \"force\": \"Medium-Full\", \"wrapper\": \"Habano Colorado Claro\", \"vitolas\": [\"Sublimes\", \"Pirámides\", \"Robusto Extra\", \"Coronas Especiales\"]}, {\"name\": \"Siglo I–VI\", \"color\": \"#8B6914\", \"story\": \"Die Clásicos — Castros ursprüngliches Sortiment. Die Siglos steigern sich von I bis VI in Länge und Intensität. Der Lancero bleibt die ultimative Prüfung für jeden kubanischen Torcedor. Das goldene Band ist zum universellen Symbol des Prestiges geworden.\", \"force\": \"Medium\", \"wrapper\": \"Habano Claro\", \"vitolas\": [\"Siglo I\", \"Siglo II\", \"Siglo III\", \"Siglo IV\", \"Siglo V\", \"Siglo VI\"]}, {\"name\": \"Maduro 5\", \"color\": \"#3D1C00\", \"story\": \"2007 lanciert, die erste Maduro im kubanischen Universum. Der Wrapper reift 5 Jahre zusätzlich in Fässern und schafft eine paradoxe Süße trotz der Stärke. Noten von Pflaume, dunkler Schokolade, geröstetem Kaffee. Heute ikonisch.\", \"force\": \"Medium-Full\", \"wrapper\": \"Habano Maduro x5\", \"vitolas\": [\"Genios\", \"Mágicos\", \"Secretos\", \"Divinos\"]}, {\"name\": \"Serie D\", \"color\": \"#5C1A00\", \"story\": \"Das Robaina — Robusto-Format (50 x 124mm), König der Formate. Dicht gerollt, entfaltet es zur Mitte des Rauchens eine unerwartete Würzkomplexität. Unverzichtbar in jedem seriösen Humidor.\", \"force\": \"Full\", \"wrapper\": \"Habano Colorado\", \"vitolas\": [\"No.4\", \"No.5\", \"No.6\"]}]', '[{\"name\": \"Behike BHK\", \"color\": \"#8B0000\", \"story\": \"2010年为品牌44周年推出，Behike是古巴历史上最稀有、最昂贵的雪茄规格。使用极为罕见的中段叶（medio tiempo）——生长在烟草植株的顶端，数量太少无法大规模采收。仅三种规格，每年仅数千盒。多位专家给予满分评价。单价：30-50欧元。\", \"force\": \"Full\", \"wrapper\": \"Habano Colorado\", \"vitolas\": [\"BHK 52\", \"BHK 54\", \"BHK 56\"], \"scores\": [{\"source\": \"Cigar Aficionado\", \"score\": 98, \"year\": 2011}]}, {\"name\": \"Línea 1492\", \"color\": \"#C04000\", \"story\": \"为纪念1992年美洲发现500周年而创。Sublimes EL和Pirámides是该品牌最稀有的规格之一，仅在特定国家作为地区版供应。Línea 1492体现了科伊巴的日常奢华——饱满而不过度。\", \"force\": \"Medium-Full\", \"wrapper\": \"Habano Colorado Claro\", \"vitolas\": [\"Sublimes\", \"Pirámides\", \"Robusto Extra\", \"Coronas Especiales\"]}, {\"name\": \"Siglo I–VI\", \"color\": \"#8B6914\", \"story\": \"经典系列——卡斯特罗的原始产品线。Siglos从I到VI递增，长度与强度逐步提升。Lancero（加长版Siglo VI）是每位古巴卷制师的终极考验。金色带饰已成为威望的普世象征。\", \"force\": \"Medium\", \"wrapper\": \"Habano Claro\", \"vitolas\": [\"Siglo I\", \"Siglo II\", \"Siglo III\", \"Siglo IV\", \"Siglo V\", \"Siglo VI\"]}, {\"name\": \"Maduro 5\", \"color\": \"#3D1C00\", \"story\": \"2007年推出，古巴雪茄界首款Maduro——一场革命。茄衣在桶中额外陈化5年，创造出矛盾的甜美感，尽管劲道十足。李子、黑巧克力、烘焙咖啡的风味。如今已成经典。\", \"force\": \"Medium-Full\", \"wrapper\": \"Habano Maduro x5\", \"vitolas\": [\"Genios\", \"Mágicos\", \"Secretos\", \"Divinos\"]}, {\"name\": \"Serie D\", \"color\": \"#5C1A00\", \"story\": \"罗巴伊纳——Robusto规格（50×124mm），规格之王。密实填充，在中段释放出意想不到的辛香复杂性。任何认真的雪茄收藏都不可或缺。\", \"force\": \"Full\", \"wrapper\": \"Habano Colorado\", \"vitolas\": [\"No.4\", \"No.5\", \"No.6\"]}]', '[{\"name\": \"Behike BHK\", \"color\": \"#8B0000\", \"story\": \"أُطلقت عام 2010 للاحتفال بالذكرى الرابعة والأربعين للعلامة، تُعدّ Behike أندر وأغلى سيجار في التاريخ الكوبي. تستخدم ورقة الميديو تيمبو النادرة للغاية — التي تنمو في قمة نبتة التبغ، صغيرة جدًا لا تُحصد على نطاق واسع. ثلاثة مقاسات فحسب، بضعة آلاف علبة سنويًا. تقييمات مثالية من خبراء متعددين. سعر الوحدة: 30-50 يورو.\", \"force\": \"Full\", \"wrapper\": \"Habano Colorado\", \"vitolas\": [\"BHK 52\", \"BHK 54\", \"BHK 56\"], \"scores\": [{\"source\": \"Cigar Aficionado\", \"score\": 98, \"year\": 2011}]}, {\"name\": \"Línea 1492\", \"color\": \"#C04000\", \"story\": \"ابتُكرت بمناسبة الذكرى الخمسمئة لاكتشاف الأمريكتين عام 1992. السوبليمس EL والبيراميدس من أندر مقاسات الدار، متوفرة فقط كإصدارات إقليمية في دول محددة.\", \"force\": \"Medium-Full\", \"wrapper\": \"Habano Colorado Claro\", \"vitolas\": [\"Sublimes\", \"Pirámides\", \"Robusto Extra\", \"Coronas Especiales\"]}, {\"name\": \"Siglo I–VI\", \"color\": \"#8B6914\", \"story\": \"الكلاسيكيات — التشكيلة الأصلية لكاسترو. تتصاعد السيغلو من الأول إلى السادس طولًا وكثافةً. يظل اللانسيرو الاختبار الأقصى لكل ملفِّف كوبي. الشريط الذهبي مع خطه الأسود أصبح الرمز العالمي للمكانة.\", \"force\": \"Medium\", \"wrapper\": \"Habano Claro\", \"vitolas\": [\"Siglo I\", \"Siglo II\", \"Siglo III\", \"Siglo IV\", \"Siglo V\", \"Siglo VI\"]}, {\"name\": \"Maduro 5\", \"color\": \"#3D1C00\", \"story\": \"أُطلقت عام 2007، أول مادورو في الكون الكوبي — ثورة حقيقية. تُعتَّق الغلافة خمس سنوات إضافية في البراميل، مُنتِجةً حلاوة متناقضة رغم القوة. نكهات البرقوق والشوكولاتة الداكنة والقهوة المحمَّصة. باتت أيقونية اليوم.\", \"force\": \"Medium-Full\", \"wrapper\": \"Habano Maduro x5\", \"vitolas\": [\"Genios\", \"Mágicos\", \"Secretos\", \"Divinos\"]}, {\"name\": \"Serie D\", \"color\": \"#5C1A00\", \"story\": \"الروباينا — مقاس روبوستو (50 × 124 ملم)، ملك المقاسات. مضغوطة بإحكام، تُطلق في منتصف التدخين تعقيدًا توابليًا غير متوقع. لا غنى عنها في أي مجموعة جادة.\", \"force\": \"Full\", \"wrapper\": \"Habano Colorado\", \"vitolas\": [\"No.4\", \"No.5\", \"No.6\"]}]', '[{\"name\": \"Fidel Castro\", \"anecdote\": \"Castro smoked 20–25 Cohiba cigars a day before quitting in 1985 on medical advice. He reportedly said: \'The best thing I did for my health was quit smoking. The best thing I did for my enemies was keep offering it to them.\'\"}, {\"name\": \"Jack Nicholson\", \"anecdote\": \"A notorious Cohiba Esplendidos smoker at his Oscar appearances, Nicholson helped popularize the brand in the United States despite the embargo.\"}, {\"name\": \"Che Guevara\", \"anecdote\": \"An iconic figure of the Cuban cigar, often photographed with a Cohiba. The image has become a global cultural symbol.\"}]', '[{\"name\": \"Fidel Castro\", \"anecdote\": \"Castro fumaba 20–25 Cohiba cigarros al día antes de dejarlo en 1985 por consejo médico. Supuestamente dijo: \'The best thing I did for my health was quit smoking. The best thing I did for my enemies was keep offering it to them.\'\"}, {\"name\": \"Jack Nicholson\", \"anecdote\": \"A notorious Cohiba Esplendidos smoker at his Oscar appearances, Nicholson helped popularize the brand in the United States despite the embargo.\"}, {\"name\": \"Che Guevara\", \"anecdote\": \"An iconic figure of the Cuban cigar, often photographed with a Cohiba. The image has become a global cultural symbol.\"}]', '[{\"name\": \"Fidel Castro\", \"anecdote\": \"Castro rauchte 20–25 Cohiba Zigarren täglich bevor er 1985 auf ärztlichen Rat aufhörte. Er soll gesagt haben: \'The best thing I did for my health was quit smoking. The best thing I did for my enemies was keep offering it to them.\'\"}, {\"name\": \"Jack Nicholson\", \"anecdote\": \"A notorious Cohiba Esplendidos smoker at his Oscar appearances, Nicholson helped popularize the brand in the United States despite the embargo.\"}, {\"name\": \"Che Guevara\", \"anecdote\": \"An iconic figure of the Cuban cigar, often photographed with a Cohiba. The image has become a global cultural symbol.\"}]', '[{\"name\": \"Fidel Castro\", \"anecdote\": \"Castro 每天抽20至25支科伊巴雪茄 在1985年遵医嘱戒烟之前. 据报道他曾说： \'The best thing I did for my health was quit smoking. The best thing I did for my enemies was keep offering it to them.\'\"}, {\"name\": \"Jack Nicholson\", \"anecdote\": \"A notorious Cohiba Esplendidos smoker at his Oscar appearances, Nicholson helped popularize the brand in the United States despite the embargo.\"}, {\"name\": \"Che Guevara\", \"anecdote\": \"An iconic figure of the Cuban cigar, often photographed with a Cohiba. The image has become a global cultural symbol.\"}]', '[{\"name\": \"Fidel Castro\", \"anecdote\": \"Castro كان يدخن من 20 إلى 25 سيجارة كوهيبا يوميًا قبل إقلاعه عام 1985 بنصيحة طبية. يُروى أنه قال: \'The best thing I did for my health was quit smoking. The best thing I did for my enemies was keep offering it to them.\'\"}, {\"name\": \"Jack Nicholson\", \"anecdote\": \"A notorious Cohiba Esplendidos smoker at his Oscar appearances, Nicholson helped popularize the brand in the United States despite the embargo.\"}, {\"name\": \"Che Guevara\", \"anecdote\": \"An iconic figure of the Cuban cigar, often photographed with a Cohiba. The image has become a global cultural symbol.\"}]', '[{\"type\": \"Spirits\", \"name\": \"Hennessy XO Cognac\", \"notes\": \"The roundness of cognac amplifies the woody notes of the Behike. A classic pairing for great occasions.\"}, {\"type\": \"Rum\", \"name\": \"Ron Santiago de Cuba 12 years\", \"notes\": \"The natural pairing — both products share the same Cuban soil. Notes of cane and tobacco in resonance.\"}, {\"type\": \"Coffee\", \"name\": \"Cuban cortadito\", \"notes\": \"The gentle bitterness of Cuban coffee perfectly supports the spiced complexity of a Siglo III after dinner.\"}]', '[{\"type\": \"Licores\", \"name\": \"Hennessy XO Cognac\", \"notes\": \"La redondez del coñac amplifica las notas maderosas of the Behike. Un maridaje clásico para grandes ocasiones.\"}, {\"type\": \"Ron\", \"name\": \"Ron Santiago de Cuba 12 years\", \"notes\": \"El maridaje natural — ambos productos comparten el mismo Cuban soil. Notas de cane and tobacco in resonance.\"}, {\"type\": \"Café\", \"name\": \"Cuban cortadito\", \"notes\": \"The gentle bitterness of Cuban coffee perfectly supports the spiced complexity of a Siglo III after dinner.\"}]', '[{\"type\": \"Spirituosen\", \"name\": \"Hennessy XO Cognac\", \"notes\": \"Die Fülle des Cognacs verstärkt die Holznoten of the Behike. Eine klassische Paarung für besondere Anlässe.\"}, {\"type\": \"Rum\", \"name\": \"Ron Santiago de Cuba 12 years\", \"notes\": \"Die natürliche Paarung — beide Produkte teilen denselben Cuban soil. Noten von cane and tobacco in resonance.\"}, {\"type\": \"Kaffee\", \"name\": \"Cuban cortadito\", \"notes\": \"The gentle bitterness of Cuban coffee perfectly supports the spiced complexity of a Siglo III after dinner.\"}]', '[{\"type\": \"烈酒\", \"name\": \"Hennessy XO Cognac\", \"notes\": \"干邑的圆润感放大了木质气息 of the Behike. 盛大场合的经典搭配.\"}, {\"type\": \"朗姆酒\", \"name\": \"Ron Santiago de Cuba 12 years\", \"notes\": \"天然的搭配 — 两种产品共享相同的 Cuban soil. 风味： cane and tobacco in resonance.\"}, {\"type\": \"咖啡\", \"name\": \"Cuban cortadito\", \"notes\": \"The gentle bitterness of Cuban coffee perfectly supports the spiced complexity of a Siglo III after dinner.\"}]', '[{\"type\": \"المسكرات\", \"name\": \"Hennessy XO Cognac\", \"notes\": \"نعومة الكونياك تُضخِّم النكهات الخشبية of the Behike. مقارنة كلاسيكية للمناسبات الكبرى.\"}, {\"type\": \"الروم\", \"name\": \"Ron Santiago de Cuba 12 years\", \"notes\": \"المقارنة الطبيعية — كلا المنتجين يشتركان في نفس Cuban soil. نكهات: cane and tobacco in resonance.\"}, {\"type\": \"القهوة\", \"name\": \"Cuban cortadito\", \"notes\": \"The gentle bitterness of Cuban coffee perfectly supports the spiced complexity of a Siglo III after dinner.\"}]'),
  ('Montecristo', '🇨🇺 Cuba', '1935 — La Havane, Cuba', 'Montecristo est née dans la légendaire manufacture H. Upmann en 1935, fondée par Alonso Menéndez et Pepe García. Le nom fut choisi par les torcedors eux-mêmes : dans les galeras de l\'époque, un lector lisait à voix haute pendant les heures de roulage — et le roman préféré de tous était Le Comte de Monte-Cristo d\'Alexandre Dumas. Le numéro 4, format Petit Corona (42 x 129mm), est aujourd\'hui le cigare le plus vendu du monde.\r\n\r\nAprès la révolution cubaine de 1959, Menéndez quitta Cuba avec ses semences et ses maîtres torcedores pour créer Montecristo en République Dominicaine — donnant naissance à deux dynasties parallèles portant le même nom glorieux. Les deux maisons se disputent depuis lors l\'héritage d\'un nom devenu mythe.\r\n\r\nLe Montecristo No.2 — formato Torpédo pyramidal — est considéré par les connaisseurs comme le cigare le plus parfaitement équilibré jamais roulé. Sa forme effilée concentre les arômes en une crescendo qui culmine en milieu de fumée avant de s\'ouvrir en une finale cèdre et épices noires d\'une longueur extraordinaire.', '[\r\n  {\"name\":\"No.2 — Le Torpedo\",\"color\":\"#8B4513\",\"story\":\"Format Torpedo (52 x 162mm), considéré par Robert Parker et de nombreux experts comme le cigare le plus parfaitement équilibré de Cuba. La forme pyramidale concentre les arômes en une montée progressive. Notes dominantes de cèdre, noisette grillée, épices douces. Durée : 90 minutes. Score Cigar Aficionado 96/100.\",\"force\":\"Medium-Full\",\"wrapper\":\"Habano Colorado\",\"vitolas\":[\"No.2\"],\"scores\":[{\"source\":\"Cigar Aficionado\",\"score\":96,\"year\":2022}]},\r\n  {\"name\":\"No.4 — Le Classique\",\"color\":\"#A0522D\",\"story\":\"Petit Corona (42 x 129mm), cigare le plus vendu du monde. Accessible, équilibré, parfait pour l\'amateur comme pour l\'expert. C\'est le Montecristo par excellence — celui que l\'on offre, que l\'on partage, que l\'on retrouve dans toutes les caves du monde. Notes de pain grillé, noix de cajou, poivre blanc.\",\"force\":\"Medium\",\"wrapper\":\"Habano Claro\",\"vitolas\":[\"No.4\"]},\r\n  {\"name\":\"Línea 1935\",\"color\":\"#722F37\",\"story\":\"Créée pour le 80ème anniversaire en 2015. Hommage direct aux origines — utilise des feuilles de Vuelta Abajo sélectionnées selon les critères de 1935. Blend plus épicé, plus corsé que la gamme classique. Édition permanente, production limitée.\",\"force\":\"Full\",\"wrapper\":\"Habano Colorado Maduro\",\"vitolas\":[\"Dumas\",\"Edmundo\",\"Maltes\"]},\r\n  {\"name\":\"Supremos EL\",\"color\":\"#4A235A\",\"story\":\"Édition régionale Espagne, format géant Supremos (54 x 185mm). L\'un des cigares les plus recherchés par les collectionneurs européens. Production annuelle inférieure à 5000 boîtes. Le temps de fumée dépasse les deux heures.\",\"force\":\"Full\",\"wrapper\":\"Habano Colorado Oscuro\",\"vitolas\":[\"Supremos\"]}\r\n]', '2026-03-18 09:43:40', '2026-03-22 15:12:47', '[{\"source\":\"Cigar Aficionado\",\"score\":96,\"year\":2022,\"vitola\":\"No.2\"},{\"source\":\"Cigar Journal\",\"score\":95,\"year\":2021,\"vitola\":\"No.4\"}]', '[{\"name\":\"Alexandre Dumas\",\"anecdote\":\"L\'auteur du Comte de Monte-Cristo n\'a jamais fumé ces cigares — il mourut en 1870 — mais son roman inspira directement le nom de la marque. Les torcedors de La Havane qui lisaient son œuvre pendant le roulage perpétuent involontairement sa mémoire.\"},{\"name\":\"JFK Kennedy\",\"anecdote\":\"La veille de signer l\'embargo cubain en 1962, Kennedy envoya son attaché de presse acheter 1200 H. Upmann Petite Upmann — les cigares préférés de Pierre Salinger. Il signa l\'embargo le lendemain avec ses cigares en sécurité.\"}]', '[{\"type\":\"Vin\",\"name\":\"Rioja Gran Reserva\",\"notes\":\"Le tanin du Rioja vieilli épouse la complexité du No.2 en une symphonie ibéro-cubaine. Accord classique des caves madrilènes.\"},{\"type\":\"Whisky\",\"name\":\"Glenfarclas 25 ans\",\"notes\":\"Les notes de xérès et de fruits secs du Glenfarclas trouvent un écho parfait dans le No.4. Accord consensuel des grandes occasions.\"},{\"type\":\"Café\",\"name\":\"Espresso ristretto\",\"notes\":\"L\'intensité réduite d\'un ristretto souligne la longueur épicée du No.2. Ne jamais noyer un Montecristo dans un café allongé.\"}]', '[\"Montecristo 80 Aniversario EL (2015)\",\"Montecristo Supremos EL (annuel, Espagne)\",\"Montecristo Gran Edmundo\",\"Montecristo Línea 1935 Maltes\"]', 'H. Upmann / Romeo y Julieta, La Havane', 'Montecristo was born inside the legendary H. Upmann factory in 1935, created by Alonso Menéndez and Pepe García from the finest tobaccos of Vuelta Abajo. The name was chosen by the torcedors themselves: during rolling sessions, a reader — the lector — would read aloud to the workers, and by consensus the favorite novel was Alexandre Dumas\' The Count of Monte Cristo. The choice revealed something about who made these cigars and what they aspired to: an epic of justice, wealth, and resurrection. The name stuck, the band was designed, and one of tobacco history\'s great dynasties began.\r\n\r\nThe early Montecristo garnered immediate attention in Britain, where the Dunhill and Hunters & Frankau networks distributed it to London\'s finest clubs. By the late 1940s, the No.4 — a Petit Corona measuring 42 x 129mm — had become the benchmark for what a daily cigar should be: not too powerful, not too delicate, impeccably constructed, and consistent across every single box. It is today the world\'s best-selling cigar, a distinction it has held for decades.\r\n\r\nThe Cuban revolution of 1959 fractured the brand into two permanent dynasties. Alonso Menéndez departed with his seeds, his master torcedores, and his institutional knowledge. He eventually settled in the Dominican Republic, where a Montecristo was created under conditions as close to the original as he could engineer. Two houses, one name, different terroir — and decades of legal disputes over the American market where the Cuban brand could not be sold due to the trade embargo.\r\n\r\nIn Havana, Montecristo continued under state ownership at the Romeo y Julieta factory. The quality recovered, the prestige deepened. The No.2, in Torpedo pyramidal format, emerged as the brand\'s intellectual masterpiece: the tapered head concentrates heat and directs aromas through the palate in a crescendo that peaks at mid-smoke before unfolding into cedar, black spice, and an impossibly long finish. Cigar Aficionado awarded it 96 points in 2022 — the highest score ever given to a regular production Cuban cigar in that publication\'s history.\r\n\r\nThe Montecristo Edmundo, launched in 2004, added a rounder, more immediate profile to the collection. The Open series brought the brand to younger smokers who found the classics slightly demanding. The Línea 1492, created for the 500th anniversary of Columbus\'s voyage in 1992, produced the Sublimes — a Double Corona of haunting complexity that connoisseurs compare to great Burgundy in the way it evolves differently in every box.\r\n\r\nWhat unites all Montecristos across formats and decades is a shared architectural philosophy: balance above all else. These are not cigars that announce themselves with power. They seduce through precision. They reward patience. And they have never stopped being the reference against which every other premium cigar is measured.', 'Montecristo nació en la legendaria fábrica H. Upmann en 1935. El nombre fue elegido por los propios torcedores: el lector en las galeras leía El Conde de Montecristo de Dumas — favorito de todos. El No.4 Petit Corona (42x129mm) es hoy el cigarro más vendido del mundo.\r\n\r\nTras la revolución de 1959, Menéndez fundó Montecristo en República Dominicana — dos dinastías paralelas con el mismo nombre glorioso.\r\n\r\nEl No.2 torpedo piramidal es considerado el cigarro cubano más perfectamente equilibrado jamás lanzado.', 'Montecristo wurde 1935 in der legendären H. Upmann Fabrik geboren. Den Namen wählten die Torcedors selbst: der Vorleser in den Galeras las Dumas\' Der Graf von Monte Christo — aller Lieblingsroman. Die No.4 Petit Corona (42x129mm) ist die meistverkaufte Zigarre der Welt.\r\n\r\nNach der Revolution 1959 gründete Menéndez Montecristo in der Dominikanischen Republik — zwei Dynastien mit demselben Namen.\r\n\r\nDie No.2 Torpedo gilt als die ausgewogenste kubanische Zigarre aller Zeiten.', '蒙特克里斯托于1935年在H·厄普曼工厂诞生。卷制师们以大仲马的《基督山伯爵》命名——那是工场朗读时人人最爱的小说。No.4小皇冠（42×129mm）是全球销量最高的雪茄。\r\n\r\n1959年革命后，梅嫩德斯在多米尼加共和国创立了蒙特克里斯托——两个平行王朝共用同一荣耀名称。\r\n\r\nNo.2锥形托尔佩多被行家视为有史以来最完美平衡的古巴雪茄。', 'وُلدت مونتيكريستو عام 1935 في مصنع H. Upmann الأسطوري. اختار الاسم الملفِّفون أنفسهم: كان القارئ في قاعات اللف يجهر برواية دوما الكونت دي مونتي كريستو — المفضلة لدى الجميع. No.4 بيتي كورونا (42×129ملم) هو أكثر السيجار مبيعًا في العالم.\r\n\r\nبعد ثورة 1959، أسّس مينينديث مونتيكريستو في جمهورية الدومينيكان — سلالتان متوازيتان بالاسم ذاته.\r\n\r\nالـ No.2 التوربيدو يُعدّ في نظر المتذوقين أكثر السيجار الكوبي توازنًا على الإطلاق.', '[{\"name\": \"No.2 — The Torpedo\", \"color\": \"#8B4513\", \"story\": \"Torpedo format (52 x 162mm) — the most perfectly balanced Cuban cigar according to many experts. The pyramidal shape creates a progressive aroma build. Dominant notes of cedar, toasted hazelnut, soft spices. Duration: 90 minutes. Cigar Aficionado score 96/100.\", \"force\": \"Medium-Full\", \"wrapper\": \"Habano Colorado\", \"vitolas\": [\"No.2\"], \"scores\": [{\"source\": \"Cigar Aficionado\", \"score\": 96, \"year\": 2022}]}, {\"name\": \"No.4 — The Classic\", \"color\": \"#A0522D\", \"story\": \"Petit Corona (42 x 129mm), the world\'s best-selling cigar. Accessible, balanced, perfect for both novice and expert. Notes of toast, cashew, white pepper.\", \"force\": \"Medium\", \"wrapper\": \"Habano Claro\", \"vitolas\": [\"No.4\"]}, {\"name\": \"Línea 1935\", \"color\": \"#722F37\", \"story\": \"Created for the 80th anniversary in 2015. A tribute to the origins — using Vuelta Abajo leaves selected per 1935 criteria. Spicier and fuller-bodied than the classic range. Permanent edition, limited production.\", \"force\": \"Full\", \"wrapper\": \"Habano Colorado Maduro\", \"vitolas\": [\"Dumas\", \"Edmundo\", \"Maltes\"]}, {\"name\": \"Supremos EL\", \"color\": \"#4A235A\", \"story\": \"Spanish regional edition, Supremos format (54 x 185mm). One of the most sought-after cigars among European collectors. Annual production under 5,000 boxes. Smoking time exceeds two hours.\", \"force\": \"Full\", \"wrapper\": \"Habano Colorado Oscuro\", \"vitolas\": [\"Supremos\"]}]', '[{\"name\": \"No.2 — The Torpedo\", \"color\": \"#8B4513\", \"story\": \"Torpedo format (52 x 162mm) — the most perfectly balanced Cuban cigar according to many experts. The pyramidal shape creates a progressive aroma build. Notas dominantes de cedro, tostado avellana, soft especias. Duración: 90 minutos. Puntuación Cigar Aficionado 96/100.\", \"force\": \"Medium-Full\", \"wrapper\": \"Habano Colorado\", \"vitolas\": [\"No.2\"], \"scores\": [{\"source\": \"Cigar Aficionado\", \"score\": 96, \"year\": 2022}]}, {\"name\": \"No.4 — The Classic\", \"color\": \"#A0522D\", \"story\": \"Petit Corona (42 x 129mm), el cigarro más vendido del mundo. Accesible, equilibrado, perfecto tanto para principiantes como para expertos. Notas de toast, cashew, white pimienta.\", \"force\": \"Medium\", \"wrapper\": \"Habano Claro\", \"vitolas\": [\"No.4\"]}, {\"name\": \"Línea 1935\", \"color\": \"#722F37\", \"story\": \"Creada para el 80º aniversario en 2015. A tribute to the origins — using Vuelta Abajo leaves selected per 1935 criteria. Spicier and fuller-bodied than the classic range. Permanent edition, limited production.\", \"force\": \"Full\", \"wrapper\": \"Habano Colorado Maduro\", \"vitolas\": [\"Dumas\", \"Edmundo\", \"Maltes\"]}, {\"name\": \"Supremos EL\", \"color\": \"#4A235A\", \"story\": \"Spanish regional edition, Supremos format (54 x 185mm). One of el más codiciado cigars among European coleccionistas. Producción anual inferior a 5.000 cajas. El tiempo de fumada supera las dos horas.\", \"force\": \"Full\", \"wrapper\": \"Habano Colorado Oscuro\", \"vitolas\": [\"Supremos\"]}]', NULL, NULL, NULL, NULL, NULL, '[{\"name\": \"No.2 — The Torpedo\", \"color\": \"#8B4513\", \"story\": \"Torpedo format (52 x 162mm) — the most perfectly balanced Cuban cigar according to many experts. The pyramidal shape creates a progressive aroma build. Dominante Noten von Zeder, geröstet Haselnuss, soft Gewürze. Dauer: 90 Minuten. Cigar Aficionado Score 96/100.\", \"force\": \"Medium-Full\", \"wrapper\": \"Habano Colorado\", \"vitolas\": [\"No.2\"], \"scores\": [{\"source\": \"Cigar Aficionado\", \"score\": 96, \"year\": 2022}]}, {\"name\": \"No.4 — The Classic\", \"color\": \"#A0522D\", \"story\": \"Petit Corona (42 x 129mm), die meistverkaufte Zigarre der Welt. Zugänglich, ausgewogen, perfekt für Anfänger und Experten gleichermaßen. Noten von toast, cashew, white Pfeffer.\", \"force\": \"Medium\", \"wrapper\": \"Habano Claro\", \"vitolas\": [\"No.4\"]}, {\"name\": \"Línea 1935\", \"color\": \"#722F37\", \"story\": \"Zum 80. Jubiläum 2015 lanciert. A tribute to the origins — using Vuelta Abajo leaves selected per 1935 criteria. Spicier and fuller-bodied than the classic range. Permanent edition, limited production.\", \"force\": \"Full\", \"wrapper\": \"Habano Colorado Maduro\", \"vitolas\": [\"Dumas\", \"Edmundo\", \"Maltes\"]}, {\"name\": \"Supremos EL\", \"color\": \"#4A235A\", \"story\": \"Spanish regional edition, Supremos format (54 x 185mm). One of die begehrteste cigars among European collectors. Jahresproduktion unter 5.000 Kisten. Rauchdauer überschreitet zwei Stunden.\", \"force\": \"Full\", \"wrapper\": \"Habano Colorado Oscuro\", \"vitolas\": [\"Supremos\"]}]', '[{\"name\": \"No.2 — The Torpedo\", \"color\": \"#8B4513\", \"story\": \"Torpedo format (52 x 162mm) — the most perfectly balanced Cuban cigar according to many experts. The pyramidal shape creates a progressive aroma build. 主导风味： 雪松木, 烘烤 榛子, soft 香料. 吸食时长：90分钟. 雪茄爱好者杂志评分 96/100.\", \"force\": \"Medium-Full\", \"wrapper\": \"Habano Colorado\", \"vitolas\": [\"No.2\"], \"scores\": [{\"source\": \"Cigar Aficionado\", \"score\": 96, \"year\": 2022}]}, {\"name\": \"No.4 — The Classic\", \"color\": \"#A0522D\", \"story\": \"Petit Corona (42 x 129mm), 全球销量最高的雪茄. 易入门，平衡，完美 适合新手和专家. 风味： toast, cashew, white 胡椒.\", \"force\": \"Medium\", \"wrapper\": \"Habano Claro\", \"vitolas\": [\"No.4\"]}, {\"name\": \"Línea 1935\", \"color\": \"#722F37\", \"story\": \"2015年为80周年推出. A tribute to the origins — using Vuelta Abajo leaves selected per 1935 criteria. Spicier and fuller-bodied than the classic range. Permanent edition, limited production.\", \"force\": \"Full\", \"wrapper\": \"Habano Colorado Maduro\", \"vitolas\": [\"Dumas\", \"Edmundo\", \"Maltes\"]}, {\"name\": \"Supremos EL\", \"color\": \"#4A235A\", \"story\": \"Spanish regional edition, Supremos format (54 x 185mm). One of 最受追捧的 cigars among European 收藏家. 年产量不足5000盒. 吸食时间超过两小时.\", \"force\": \"Full\", \"wrapper\": \"Habano Colorado Oscuro\", \"vitolas\": [\"Supremos\"]}]', '[{\"name\": \"No.2 — The Torpedo\", \"color\": \"#8B4513\", \"story\": \"Torpedo format (52 x 162mm) — the most perfectly balanced Cuban cigar according to many experts. The pyramidal shape creates a progressive aroma build. النكهات المهيمنة:  أرز, محمَّص بندق, soft توابل. مدة التدخين: 90 دقيقة. تقييم Cigar Aficionado 96/100.\", \"force\": \"Medium-Full\", \"wrapper\": \"Habano Colorado\", \"vitolas\": [\"No.2\"], \"scores\": [{\"source\": \"Cigar Aficionado\", \"score\": 96, \"year\": 2022}]}, {\"name\": \"No.4 — The Classic\", \"color\": \"#A0522D\", \"story\": \"Petit Corona (42 x 129mm), أكثر السيجار مبيعًا في العالم. سهل الوصول، متوازن، مثالي للمبتدئ والخبير على حدٍّ سواء. نكهات:  toast, cashew, white فلفل.\", \"force\": \"Medium\", \"wrapper\": \"Habano Claro\", \"vitolas\": [\"No.4\"]}, {\"name\": \"Línea 1935\", \"color\": \"#722F37\", \"story\": \"أُبدعت للذكرى الثمانين عام 2015. A tribute to the origins — using Vuelta Abajo leaves selected per 1935 criteria. Spicier and fuller-bodied than the classic range. Permanent edition, limited production.\", \"force\": \"Full\", \"wrapper\": \"Habano Colorado Maduro\", \"vitolas\": [\"Dumas\", \"Edmundo\", \"Maltes\"]}, {\"name\": \"Supremos EL\", \"color\": \"#4A235A\", \"story\": \"Spanish regional edition, Supremos format (54 x 185mm). One of الأكثر طلبًا cigars among European الجامعون. الإنتاج السنوي أقل من 5000 علبة. تتجاوز مدة التدخين ساعتين.\", \"force\": \"Full\", \"wrapper\": \"Habano Colorado Oscuro\", \"vitolas\": [\"Supremos\"]}]', '[{\"name\": \"Alexandre Dumas\", \"anecdote\": \"The author of The Count of Monte Cristo never smoked these cigars — he died in 1870 — but his novel directly inspired the brand name. The Havana torcedors who read his work during rolling sessions inadvertently perpetuate his memory.\"}, {\"name\": \"JFK Kennedy\", \"anecdote\": \"The night before signing the Cuban embargo in 1962, Kennedy sent his press secretary to buy 1,200 H. Upmann cigars. He signed the embargo the next day with his supply secure.\"}]', '[{\"name\": \"Alexandre Dumas\", \"anecdote\": \"The author of The Count of Monte Cristo never fumaba these cigars — he died in 1870 — but his novel directly inspired the brand name. The Havana torcedors who read his work during rolling sessions inadvertently perpetuate his memory.\"}, {\"name\": \"JFK Kennedy\", \"anecdote\": \"The night before signing the Cuban embargo in 1962, Kennedy sent his press secretary to buy 1,200 H. Upmann cigars. He signed the embargo the next day with his supply secure.\"}]', '[{\"name\": \"Alexandre Dumas\", \"anecdote\": \"The author of The Count of Monte Cristo never rauchte these cigars — he died in 1870 — but his novel directly inspired the brand name. The Havana torcedors who read his work during rolling sessions inadvertently perpetuate his memory.\"}, {\"name\": \"JFK Kennedy\", \"anecdote\": \"The night before signing the Cuban embargo in 1962, Kennedy sent his press secretary to buy 1,200 H. Upmann cigars. He signed the embargo the next day with his supply secure.\"}]', '[{\"name\": \"Alexandre Dumas\", \"anecdote\": \"The author of The Count of Monte Cristo never smoked these cigars — he died in 1870 — but his novel directly inspired the brand name. The Havana torcedors who read his work during rolling sessions inadvertently perpetuate his memory.\"}, {\"name\": \"JFK Kennedy\", \"anecdote\": \"The night before signing the Cuban embargo in 1962, Kennedy sent his press secretary to buy 1,200 H. Upmann cigars. He signed the embargo the next day with his supply secure.\"}]', '[{\"name\": \"Alexandre Dumas\", \"anecdote\": \"The author of The Count of Monte Cristo never smoked these cigars — he died in 1870 — but his novel directly inspired the brand name. The Havana torcedors who read his work during rolling sessions inadvertently perpetuate his memory.\"}, {\"name\": \"JFK Kennedy\", \"anecdote\": \"The night before signing the Cuban embargo in 1962, Kennedy sent his press secretary to buy 1,200 H. Upmann cigars. He signed the embargo the next day with his supply secure.\"}]', '[{\"type\": \"Wine\", \"name\": \"Rioja Gran Reserva\", \"notes\": \"The tannin of aged Rioja embraces the complexity of the No.2 in an Ibero-Cuban symphony.\"}, {\"type\": \"Whisky\", \"name\": \"Glenfarclas 25 years\", \"notes\": \"The sherry and dried fruit notes find a perfect echo in the No.4. A pairing for great occasions.\"}, {\"type\": \"Coffee\", \"name\": \"Ristretto espresso\", \"notes\": \"The intensity of a ristretto highlights the spiced length of the No.2.\"}]', '[{\"type\": \"Vino\", \"name\": \"Rioja Gran Reserva\", \"notes\": \"The tannin of aged Rioja embraces the complexity of the No.2 in an Ibero-Cuban symphony.\"}, {\"type\": \"Whisky\", \"name\": \"Glenfarclas 25 years\", \"notes\": \"The sherry and dried fruit notes find a perfect echo in the No.4. A pairing for great occasions.\"}, {\"type\": \"Café\", \"name\": \"Ristretto espresso\", \"notes\": \"The intensity of a ristretto highlights the spiced length of the No.2.\"}]', '[{\"type\": \"Wein\", \"name\": \"Rioja Gran Reserva\", \"notes\": \"The tannin of aged Rioja embraces the complexity of the No.2 in an Ibero-Cuban symphony.\"}, {\"type\": \"Whisky\", \"name\": \"Glenfarclas 25 years\", \"notes\": \"The sherry and dried fruit notes find a perfect echo in the No.4. A pairing for great occasions.\"}, {\"type\": \"Kaffee\", \"name\": \"Ristretto espresso\", \"notes\": \"The intensity of a ristretto highlights the spiced length of the No.2.\"}]', '[{\"type\": \"葡萄酒\", \"name\": \"Rioja Gran Reserva\", \"notes\": \"The tannin of aged Rioja embraces the complexity of the No.2 in an Ibero-Cuban symphony.\"}, {\"type\": \"威士忌\", \"name\": \"Glenfarclas 25 years\", \"notes\": \"The sherry and dried fruit notes find a perfect echo in the No.4. A pairing for great occasions.\"}, {\"type\": \"咖啡\", \"name\": \"Ristretto espresso\", \"notes\": \"The intensity of a ristretto highlights the spiced length of the No.2.\"}]', '[{\"type\": \"النبيذ\", \"name\": \"Rioja Gran Reserva\", \"notes\": \"The tannin of aged Rioja embraces the complexity of the No.2 in an Ibero-Cuban symphony.\"}, {\"type\": \"الويسكي\", \"name\": \"Glenfarclas 25 years\", \"notes\": \"The sherry and dried fruit notes find a perfect echo in the No.4. A pairing for great occasions.\"}, {\"type\": \"القهوة\", \"name\": \"Ristretto espresso\", \"notes\": \"The intensity of a ristretto highlights the spiced length of the No.2.\"}]'),
  ('Partagás', '🇨🇺 Cuba', '1845 — La Havane, Cuba', 'Don Jaime Partagás fonda sa manufacture en 1845 dans le Barrio de los Sitios de La Havane — et elle n\'a jamais quitté l\'adresse originale, Calle Industria 520. Pendant 175 ans, l\'édifice néoclassique a résisté aux révolutions, aux ouragans et aux embargos. C\'est la plus ancienne manufacture de cigares encore en activité au monde.\r\n\r\nPartagás fut le premier à payer ses ouvriers pour qu\'un lecteur leur fasse la lecture à voix haute — Don Jaime pensait que des esprits cultivés produisaient de meilleurs cigares. Cette pratique, la lectura, se répandit ensuite dans toutes les manufactures cubaines et dans les communautés de torcedores en exil à Tampa et Miami.\r\n\r\nLa marque est connue pour ses cigares corsés, expressifs, terreux — l\'opposé de la sophistication froide de Cohiba. Les amateurs de Partagás sont fidèles jusqu\'à l\'extrême : on ne passe pas de Partagás à une autre marque, on en revient toujours. La Série D No.4, la Lusitanias et la 8-9-8 Varnished sont les trois trésors de la maison.', '[\r\n  {\"name\":\"Série D\",\"color\":\"#8B2500\",\"story\":\"La Série D No.4 — Robusto 50 x 124mm — est le cigare full-body de référence absolue. Terreux, puissant, complexe. Notes de cacao amer, poivre noir, sous-bois humide. Fumée en 45 minutes, elle ne pardonne pas une conservation négligée. Score Cigar Aficionado 93. Le No.4 est souvent le premier cigare vraiment corsé que découvre un amateur confirmé — et il ne s\'en remet pas.\",\"force\":\"Full\",\"wrapper\":\"Habano Colorado Oscuro\",\"vitolas\":[\"No.4\",\"No.5\"]},\r\n  {\"name\":\"Lusitanias\",\"color\":\"#722F37\",\"story\":\"Format Double Corona (49 x 194mm), 90 minutes de fumée. L\'un des rares formats géants encore produits régulièrement à Cuba. Nommée en hommage au paquebot coulé en 1915. La Lusitanias est le cigare des grandes occasions solennelles — elle n\'admet ni précipitation ni distraction. Éditions limitées Lusitanias Gran Reserva disponibles chez des revendeurs sélectifs.\",\"force\":\"Full\",\"wrapper\":\"Habano Oscuro\",\"vitolas\":[\"Lusitanias\"]},\r\n  {\"name\":\"8-9-8 Collection\",\"color\":\"#5C4033\",\"story\":\"Commercialisée en boîtes de 25 cigares rangés 8-9-8 — d\'où le nom. Format Panetela (33 x 170mm), le plus fin jamais produit à Cuba. Légèreté apparente trompeuse : la finesse du calibre concentre les arômes en une intensité inattendue. Format adulé des amateurs parisiens.\",\"force\":\"Medium-Full\",\"wrapper\":\"Habano Claro\",\"vitolas\":[\"8-9-8 Varnished\"]},\r\n  {\"name\":\"Habaneros\",\"color\":\"#A0522D\",\"story\":\"La gamme d\'entrée — mais chez Partagás, \'entrée\' est relatif. Les Habaneros Short sont les cigares de plaisir quotidien des Havanais eux-mêmes. Courts (42 x 110mm), intenses, à fumer en 20 minutes. La vraie saveur cubaine populaire, sans cérémonie.\",\"force\":\"Medium-Full\",\"wrapper\":\"Habano Claro\",\"vitolas\":[\"Short\",\"Club\"]}\r\n]', '2026-03-18 09:43:40', '2026-03-22 15:12:47', '[{\"source\":\"Cigar Aficionado\",\"score\":93,\"year\":2020,\"vitola\":\"Serie D No.4\"},{\"source\":\"Cigar Journal\",\"score\":94,\"year\":2019,\"vitola\":\"Lusitanias\"}]', '[{\"name\":\"Somerset Maugham\",\"anecdote\":\"L\'auteur britannique décrivit la Partagás Lusitanias comme \'la seule chose pour laquelle je ferais le voyage jusqu\'à La Havane\'. Il en faisait livrer des boîtes à Londres via l\'ambassade.\"},{\"name\":\"Groucho Marx\",\"anecdote\":\"Marx fumait des cigares en permanence sur scène et dans la vie. Il aurait dit : \'Un cigare à ce stade n\'est plus un vice. C\'est une philosophie.\'\"}]', '[{\"type\":\"Spiritueux\",\"name\":\"Armagnac Bas-Armagnac 20 ans\",\"notes\":\"La profondeur terreuse de l\'Armagnac vieillit résonne avec le côté rustique puissant d\'une Serie D. Accord pour connaisseurs.\"},{\"type\":\"Bière\",\"name\":\"Porter irlandais\",\"notes\":\"Surprenant mais redoutable — le café torréfié d\'un Good Things Stout amplifie les notes de cacao de la Serie D.\"},{\"type\":\"Thé\",\"name\":\"Pu-erh vieilli 10 ans\",\"notes\":\"Le Pu-erh fermenté, terreux et profond, est l\'accord thé ultime avec Partagás. Les deux partagent la même complexité tellurique.\"}]', '[\"Partagás Lusitanias Gran Reserva Cosecha 2014\",\"Partagás Serie D No.4 Gran Reserva\",\"Partagás 170 Aniversario EL (2015)\",\"Partagás P Series EL\"]', 'Manufactura Partagás, Calle Industria 520, La Havane — fondée 1845', 'Don Jaime Partagás founded his factory in 1845 in Havana\'s Barrio de los Sitios, on a street that would one day bear his name. At Calle Industria 520, the neoclassical building he constructed has never moved, never closed, never reinvented itself into something unrecognizable. For 180 years it has survived Spanish colonial rule, American occupation, two world wars, a revolution, a half-century of embargo, and the slow collapse of everything around it. It is today the oldest cigar factory still in active production anywhere in the world — a distinction that is architectural, historical, and entirely earned.\r\n\r\nDon Jaime was a restless innovator in an era when most manufacturers simply maintained tradition. He traveled to the tobacco fields himself. He understood that the earthy, powerful profile his factory produced required tobaccos from specific micro-regions of Vuelta Abajo — the deep red soils near San Luis and San Juan y Martínez that impart the characteristic dark cocoa and forest floor complexity that defines the Partagás style. He paid premiums for those leaves when his competitors did not.\r\n\r\nHis most enduring contribution was not commercial but cultural. Partagás was the first manufacturer in Cuba — and possibly in the world — to employ a lector: a professional reader who sat on an elevated platform in the rolling gallery and read aloud to the torcedores throughout the working day. The practice transformed the factory floor into an unlikely salon. Workers heard Zola, Dickens, Victor Hugo, and Marx. They debated what they heard. They requested specific texts. Don Jaime believed that cultivated minds produced better cigars — and the quality of Partagás under his direction supported the theory. La lectura spread to every Cuban factory, then to exiled torcedore communities in Tampa, Key West, and New York, where it survived well into the twentieth century.\r\n\r\nAfter Don Jaime\'s death in 1868 — murdered, the legend says, by a rival — the factory passed through several hands before being nationalized in 1960. The state maintained the address, the workforce, and most importantly the tobacco sourcing. The Serie D No.4, a Robusto measuring 50 x 124mm, became under Cuban state management what it remains today: the global benchmark for full-body cigars. Its notes of bitter cocoa, black pepper, damp undergrowth, and aged cedar arrive in waves across 45 minutes of consistent, escalating complexity. Cigar Aficionado has awarded it scores between 92 and 95 across fifteen consecutive reviews.\r\n\r\nThe Lusitanias — a Double Corona measuring 49 x 194mm — is one of the last great format cigars still produced regularly in Cuba. Ninety minutes in the hand. Five distinct aromatic phases. The 8-9-8 Varnished, sold in cedar boxes with cigars arranged in the namesake pattern, is the house\'s most elegant proposition: a Panetela so narrow it seems impossibly fragile, yet concentrates aromas with an intensity that surprises every smoker who approaches it expecting lightness. These three cigars — the Serie D, the Lusitanias, the 8-9-8 — form a triangle that has defined serious cigar culture for a century and shows no sign of becoming irrelevant.', 'Don Jaime Partagás fundó su fábrica en 1845 en el Barrio de los Sitios de La Habana, en la Calle Industria 520 — dirección que nunca ha abandonado. Es la fábrica más antigua del mundo aún en funcionamiento.\r\n\r\nPartagás fue el pionero de la lectura: un lector leía en voz alta a los obreros durante el trabajo. Esta práctica se extendió por todas las fábricas cubanas.\r\n\r\nSus cigarros son robustos, terrosos, expresivos. Los aficionados a Partagás son fieles hasta el extremo: siempre se vuelve.', 'Don Jaime Partagás gründete 1845 seine Fabrik in der Calle Industria 520 in Havanna — eine Adresse, die sie nie verlassen hat. Es ist die älteste Zigarrenfabrik der Welt.\r\n\r\nPartagás erfand die Lectura: Ein Vorleser las den Arbeitern während der Arbeit vor. Diese Praxis verbreitete sich in ganz Kuba.\r\n\r\nKräftige, erdige, ausdrucksstarke Zigarren. Partagás-Fans sind bedingungslos treu — man kommt immer zurück.', '唐·海梅·帕特加斯于1845年在哈瓦那工业街520号创立了他的工厂——至今从未离开。它是全球仍在运营的最古老雪茄工厂。\r\n\r\n帕特加斯首创了朗读传统：在工作时朗读者为工人大声朗读。这一习俗传遍古巴所有工厂。\r\n\r\n浓郁、有力、泥土气息的雪茄。帕特加斯爱好者极其忠诚——总会回来。', 'أسّس دون خايمي بارتاغاس مصنعه عام 1845 في كاييه إنداستريا 520 بهافانا — عنوان لم يغادره قط. إنه أقدم مصنع سيجار في العالم لا يزال يعمل.\r\n\r\nكان بارتاغاس رائدًا في الليكتورا: قارئ يجهر للعمال أثناء اللف. انتشرت هذه العادة في جميع مصانع كوبا.\r\n\r\nسيجار قوي ترابي معبِّر. عشاق بارتاغاس أوفياء دائمًا — ستعود إليها في نهاية المطاف.', '[{\"name\": \"Serie D\", \"color\": \"#8B2500\", \"story\": \"The Serie D No.4 — Robusto 50 x 124mm — is the absolute full-body reference cigar. Earthy, powerful, complex. Notes of bitter cocoa, black pepper, damp forest floor. Smoked in 45 minutes, it does not forgive improper storage. Cigar Aficionado score 93.\", \"force\": \"Full\", \"wrapper\": \"Habano Colorado Oscuro\", \"vitolas\": [\"No.4\", \"No.5\"]}, {\"name\": \"Lusitanias\", \"color\": \"#722F37\", \"story\": \"Double Corona format (49 x 194mm), 90 minutes of smoke. One of the few giant formats still regularly produced in Cuba. Named for the ocean liner sunk in 1915. A cigar for solemn great occasions — it tolerates neither haste nor distraction.\", \"force\": \"Full\", \"wrapper\": \"Habano Oscuro\", \"vitolas\": [\"Lusitanias\"]}, {\"name\": \"8-9-8 Collection\", \"color\": \"#5C4033\", \"story\": \"Sold in boxes of 25 arranged 8-9-8. Panetela format (33 x 170mm), the finest ever produced in Cuba. Deceptive lightness: the narrow ring gauge concentrates aromas into unexpected intensity. Beloved by Parisian enthusiasts.\", \"force\": \"Medium-Full\", \"wrapper\": \"Habano Claro\", \"vitolas\": [\"8-9-8 Varnished\"]}, {\"name\": \"Habaneros\", \"color\": \"#A0522D\", \"story\": \"The entry-level range — but at Partagás, \'entry\' is relative. The Habaneros Short are the everyday pleasure cigars of Havanans themselves. Short (42 x 110mm), intense, smoked in 20 minutes. The true popular Cuban flavor, without ceremony.\", \"force\": \"Medium-Full\", \"wrapper\": \"Habano Claro\", \"vitolas\": [\"Short\", \"Club\"]}]', '[{\"name\": \"Serie D\", \"color\": \"#8B2500\", \"story\": \"The Serie D No.4 — Robusto 50 x 124mm — is the absolute full-body reference cigar. Earthy, powerful, complex. Notas de bitter cocoa, pimienta negra, damp forest floor. Fumado en 45 minutos, it does not forgive improper storage. Puntuación Cigar Aficionado 93.\", \"force\": \"Full\", \"wrapper\": \"Habano Colorado Oscuro\", \"vitolas\": [\"No.4\", \"No.5\"]}, {\"name\": \"Lusitanias\", \"color\": \"#722F37\", \"story\": \"Double Corona format (49 x 194mm), 90 minutos of smoke. One of the few giant formats still regularly produced in Cuba. Nombrada por the ocean liner sunk in 1915. A cigar for solemn great occasions — it tolerates neither haste nor distraction.\", \"force\": \"Full\", \"wrapper\": \"Habano Oscuro\", \"vitolas\": [\"Lusitanias\"]}, {\"name\": \"8-9-8 Collection\", \"color\": \"#5C4033\", \"story\": \"Sold in boxes of 25 arranged 8-9-8. Panetela format (33 x 170mm), the finest ever produced in Cuba. Deceptive lightness: the narrow ring gauge concentrates aromas into unexpected intensity. Beloved by Parisian aficionados.\", \"force\": \"Medium-Full\", \"wrapper\": \"Habano Claro\", \"vitolas\": [\"8-9-8 Varnished\"]}, {\"name\": \"Habaneros\", \"color\": \"#A0522D\", \"story\": \"The entry-level range — but at Partagás, \'entry\' is relative. The Habaneros Short are the everyday pleasure cigars of Havanans themselves. Short (42 x 110mm), intense, smoked in 20 minutes. The true popular Cuban flavor, without ceremony.\", \"force\": \"Medium-Full\", \"wrapper\": \"Habano Claro\", \"vitolas\": [\"Short\", \"Club\"]}]', NULL, NULL, NULL, NULL, NULL, '[{\"name\": \"Serie D\", \"color\": \"#8B2500\", \"story\": \"The Serie D No.4 — Robusto 50 x 124mm — is the absolute full-body reference cigar. Earthy, powerful, complex. Noten von bitter cocoa, schwarzer Pfeffer, damp forest floor. Geraucht in 45 Minuten, it does not forgive improper storage. Cigar Aficionado Score 93.\", \"force\": \"Full\", \"wrapper\": \"Habano Colorado Oscuro\", \"vitolas\": [\"No.4\", \"No.5\"]}, {\"name\": \"Lusitanias\", \"color\": \"#722F37\", \"story\": \"Double Corona format (49 x 194mm), 90 Minuten of smoke. One of the few giant formats still regularly produced in Cuba. Benannt nach the ocean liner sunk in 1915. A cigar for solemn great occasions — it tolerates neither haste nor distraction.\", \"force\": \"Full\", \"wrapper\": \"Habano Oscuro\", \"vitolas\": [\"Lusitanias\"]}, {\"name\": \"8-9-8 Collection\", \"color\": \"#5C4033\", \"story\": \"Sold in boxes of 25 arranged 8-9-8. Panetela format (33 x 170mm), the finest ever produced in Cuba. Deceptive lightness: the narrow ring gauge concentrates aromas into unexpected intensity. Beloved by Parisian enthusiasts.\", \"force\": \"Medium-Full\", \"wrapper\": \"Habano Claro\", \"vitolas\": [\"8-9-8 Varnished\"]}, {\"name\": \"Habaneros\", \"color\": \"#A0522D\", \"story\": \"The entry-level range — but at Partagás, \'entry\' is relative. The Habaneros Short are the everyday pleasure cigars of Havanans themselves. Short (42 x 110mm), intense, smoked in 20 minutes. The true popular Cuban flavor, without ceremony.\", \"force\": \"Medium-Full\", \"wrapper\": \"Habano Claro\", \"vitolas\": [\"Short\", \"Club\"]}]', '[{\"name\": \"Serie D\", \"color\": \"#8B2500\", \"stor